WordHunterWoW_QuestDataByFlavor = WordHunterWoW_QuestDataByFlavor or {}
WordHunterWoW_QuestDataByFlavor.classic = WordHunterWoW_QuestDataByFlavor.classic or {}
WordHunterWoW_QuestDataByFlavor.classic.enUS = WordHunterWoW_QuestDataByFlavor.classic.enUS or {}
local quests = WordHunterWoW_QuestDataByFlavor.classic.enUS
quests[527] = { title = "Battle of Hillsbrad", description = "Stand at attention while addressing me, $c.\n\nI am under direct command of Varimathras.  We are to quell the human infestation until our apothecaries can develop the new plague.\n\nOur information leads us to believe that the town of Hillsbrad is vulnerable to attack.  Your first assignment is aimed at disrupting their food supply and infrastructure.\n\nTravel west.  Raid the northernmost farms of Hillsbrad Fields.  Make sure that the landowners, Farmer Ray and Farmer Getz, are executed as well.", objectives = "Kill 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray and Farmer Getz and report back to Darthalia in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[528] = { title = "Battle of Hillsbrad", description = "Word of the attack on the northern farms has the townsfolk panicked.  Most excellent.\n\nOur Deathstalkers report peasants fleeing to the fields in southern Hillsbrad.  The fools think they can hide in the orchards and escape their doom.\n\nProve them wrong, $N.  Return to Hillsbrad Fields and seek out the cowering peasants.  Lay waste to them in the name of our Dark Lady.\n\nDismissed!", objectives = "Kill 15 Hillsbrad Peasants and report back to Darthalia in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[529] = { title = "Battle of Hillsbrad", description = "The humans of Hillsbrad have been putting up unexpected resistance.  The problem appears to be that the townsfolk are being armed by the local blacksmith.  We need to shut down all supply lines.\n\nYour mission will be to execute Blacksmith Verringtan.  Slay his apprentices as well.  While there, bring back a shipment of iron from their stockpile.  The supplies will come in handy when we are done with the conquering of Hillsbrad and begin razing Southshore.", objectives = "Kill Blacksmith Verringtan and 4 Hillsbrad Apprentice Blacksmiths.\n\nRetrieve a shipment of iron and report back to Darthalia in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[530] = { title = "A Husband's Revenge", description = "Valdred, once my good friend, was my wife's murderer.  Although I am incapable of grieving, I do yearn for revenge.  If you kill Valdred and bring me his cursed hands, then I will reward you.\n\nI last heard he was at the Greymane Wall in southern Silverpine, trying to flee into the kingdom of Gilneas.", objectives = "Kill Valdred Moray.\n\nBring his hands to Raleigh Andrean in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[531] = { title = "Vyrin's Revenge", description = "Light! Don't bring things like that into the Lodge... it's unsanitary, unspeakable, un... un... unsanitary!\n\nJust get it out of here, will you? No one wants to see your bloody little trophy, really!", objectives = "Bring Ol' Sooty's head to Vyrin Swiftwind at the Farstrider Lodge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[532] = { title = "Battle of Hillsbrad", description = "The town of Hillsbrad is in disarray and we believe it will soon fall.  We must, however, persist in our ruthlessness until the human scum are wiped from the foothills for eternity.\n\nDespite their overwhelming losses, the humans rally around their leadership and keep fighting.  We must eliminate their leader, Magistrate Burnside, as well as the town council.  Destroy their revered political document as well, the Hillsbrad Proclamation.  And while you're at it, steal the town registry.", objectives = "Kill Magistrate Burnside and 5 Hillsbrad Councilmen.  Destroy the Hillsbrad Proclamation.  Steal the Hillsbrad Town Registry.  Report back to Darthalia in Tarren Mill afterwards.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[533] = { title = "Infiltration", description = "At last we begin to hear word and rumor, find evidence of Gol'dir's whereabouts. The humans have been moving him around, but we are narrowing down our search and focusing on the large Syndicate camp just north of here.\n\nGo there, $n, and bring back whatever information you can get your hands on.", objectives = "Retrieve information about Gol'dir's whereabouts for Krusk in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[535] = { title = "Valik", description = "Urrgh... Injured and dying and confronted with the enemy.\n\nNo doubt you'll kill me anyway, but if you bring me some Southshore stout--your kind does drink, don't they?--I'll tell you what you want to know.", objectives = "Bring a mug of Southshore Stout to Valik in the Syndicate camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[536] = { title = "Down the Coast", description = "Transferred from the Stormwind city guard to Southshore, a town that should be abandoned by the looks of it... Smell of the harbor day and night.\n\nNot to mention ol' Redpath... Wants me to take care of the murlocs. Ha! \n\nI can barely rouse myself to go out to some of the pockets of the overgrown fish down the Western Strand. If you would go in my place and take care of them, I'd appreciate it.", objectives = "Kill 10 Torn Fin Tidehunters and 10 Torn Fin Oracles for Lieutenant Farren Orinelle in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[537] = { title = "Dark Council", description = "The letter you brought me was written by a being who calls himself Nagaz, a member of the Argus Wake.  I don't know what this Argus Wake is, but if they're in alliance with the Syndicate then they must be a threat.\n\nI want you to find Nagaz and the Argus Shadow Mages mentioned in that letter.  I want you to find them, and kill them.\n\nSearch in the Uplands, where the Syndicate is strongest.  It is north of Strahnbrad.\n\nWith luck, you'll find these envoys of the Argus Wake there.", objectives = "Kill 4 Argus Shadow Mages.\n\nBring the Head of Nagaz to Magistrate Maleb in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[538] = { title = "Southshore", description = "$N.  If you don't mind a long journey then I have a task for you, to again help Stormwind fill its library.\n\nThe old kingdom of Alterac fell after the great war, and it had a large collection of books.  It's a tragedy that the city is ruined, but even more tragic is all of their knowledge lost!  We must recover what we can.\n\nSouthshore is the closest town to the Ruins of Alterac.  Go there and speak with Loremaster Dibbs.  He can direct you to the ruins, and to what books may be found there.", objectives = "Speak with Loremaster Dibbs in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[539] = { title = "Battle of Hillsbrad", description = "The Hillsbrad Town Registry indicates that the Azureload Mine is under Alliance control.  Furthermore, the mine is a prime source of iron ore for the Alliance armories.\n\nEven though we've struck a decisive blow to the town of Hillsbrad, the Alliance still supports and protects the Azureload Mine fervently.\n\nThe mine lies due south of Hillsbrad.  Go there and slay the foreman, a human by the name of Bonds.  Kill his miners as well.  That should send a clear message to the Alliance.", objectives = "Kill Foreman Bonds and 10 Hillsbrad Miners and report back to Darthalia in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[540] = { title = "Preserving Knowledge", description = "Those beastly ogres now reside within Alterac's ruins, and I shudder to think what they're doing with the precious books still there.  You must recover what you can!\n\nEnter the Ruins of Alterac and search for tomes looted by the ogres.  Get whatever you can find and bring them to me, but also seek out one book in particular: The Arm of Gri'lek.  It contains ancient troll lore that I must learn, and the Ruins of Alterac was the last known location of an intact copy of this book.", objectives = "Bring 5 Recovered Tomes and the Worn Leather Book containing The Arm of Gri'lek to Loremaster Dibbs in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[541] = { title = "Battle of Hillsbrad", description = "Dwarves aiding the humans?  Damn those filthy little beasts.\n\nWe shall test the strength of the so-called Alliance.  We'll see how anxious those little ankle-bashers are to help the humans once they feel our wrath.  We know exactly where their stronghold is in this territory.\n\nThey have established a barracks in southeastern Hillsbrad along Thoradin's Wall called Dun Garok.  The final mission of this battle is to lay siege on Dun Garok, $c.  Captain Ironhill, their leader, must die.", objectives = "Travel to Dun Garok and kill 10 Mountaineers, 8 Riflemen, 4 Priests and Captain Ironhill and report back to Darthalia in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[542] = { title = "Return to Milton", description = "I need to spend some time studying the Arm of Gri'lek book you brought me, though I'm sure Milton is eager to get the other recovered books into Stormwind's collection.\n\nHere are the books you gathered from the Ruins of Alterac, packed and catalogued.  Take them back to Milton Sheaf in Stormwind and I'm sure he'll be grateful.", objectives = "Bring the Tomes of Alterac to Milton Sheaf in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[543] = { title = "The Perenolde Tiara", description = "The Perenolde Tiara is an old heirloom of the Perenolde \"nobles\" - the ruling family of Alterac before that kingdom fell to ruin.  It is said to have been crafted by master jewelers in Ironforge, and fitted with the finest of emeralds.\n\nWhen Alterac was destroyed the Tiara was lost, but there are rumors that an Ogre Mage, Grel'borg the Miser, found the tiara and now wanders the Ruins of Alterac searching for more treasures.\n\nWe would have you acquire the tiara for us.", objectives = "Bring the Perenolde Tiara to Remington Ridgewell in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[544] = { title = "Prison Break In", description = "I came to Tarren Mill to research, but now must resolve a crisis.  You see, four Forsaken fled the Undercity a few months ago.  They turned their backs on their brethren, but what's worse...they stole from the Dark Lady.\n\nThese thieves broke into a secure vault and stole four artifacts, items our apothecaries required in certain studies.  Sylvanas would have these artifacts returned.\n\nThe thieves fled the Undercity to Dalaran, and those wizards quarantined them in the Lordamere Internment Camp.", objectives = "Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[545] = { title = "Dalaran Patrols", description = "The wizards of Dalaran constructed a vast, magical dome around the heart of their city.  Some believe it was for protection from the violence of these times, while others say they merely wanted solitude, to study and plot.\n\nI don't care what the reason was.  I do care that the ruined outskirts of their city, outside the dome, may hide valuable magical treasures.\n\nBut the area is patrolled by the wizards and their elemental slaves.\n\nSo hunt them, and return when their numbers are sufficiently reduced.", objectives = "Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[546] = { title = "Souvenirs of Death", description = "I hear you were enlisted by Darthalia to wage war on the humans of Hillsbrad.  So jealous I am. . .\n\nWhile you're off having all the fun -- slaying humans, pillaging the town, terrorizing innocent people -- I am stuck standing guard here in Tarren Mill.\n\nPerhaps you'll take pity on an old Deathguard like myself?  You see I am collecting human skulls.  And you will be fighting humans for quite some time.  Over the course of your long battle, bring me 30 skulls and I will make it worth your while.", objectives = "Deathguard Samsa of Tarren Mill wants 30 Hillsbrad Human Skulls.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[547] = { title = "Humbert's Sword", description = "High Executor Darthalia sent me to keep watch of Dun Garok from a distance.  I had set up camp just out of sight.  But when morning came and I had to boil water, I left to gather firewood.\n\nWhen I returned to camp, I discovered my gear was missing.\n\nApparently some dwarven scouts from Dun Garok had passed by and made off with it.  I need my sword!  If you can get it back for me I would be so grateful.  So many dwarves there...it will be quite difficult to find the dirty little thief who stole it.", objectives = "Retrieve Deathguard Humbert's sword from Dun Garok and return it to him in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[549] = { title = "WANTED: Syndicate Personnel", description = "By the authority of Lady Sylvanas, all members of the organization known as the Syndicate are wanted dead. Those brought into custody or taken prisoner will be summarily executed. They are currently known to be amassing in the ruins of Durnholde Keep, to the southeast of Tarren Mill.\n\nA handsome reward is offered to all who bring proof of their deeds to High Executor Darthalia.", objectives = "Kill 10 Syndicate Rogues and 10 Syndicate Watchmen. Return to High Executor Darthalia in Tarren Mill for your reward.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[550] = { title = "Battle of Hillsbrad", description = "Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize.\n\nTake this sealed commendation to Varimathras in the Undercity.  Go with pride, $c.", objectives = "Take Darthalia's Sealed Commendation to Varimathras in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[551] = { title = "The Ensorcelled Parchment", description = "This parchment is enchanted with a spell, rendering it indecipherable.  But one word at the top of the paper can be read:\n\n\n      Nagaz\n\n", objectives = "Take the Ensorcelled Parchment to Loremaster Dibbs in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[552] = { title = "Helcular's Revenge", description = "Master Helcular was almost complete with his transformation into a Lich when a human lynch mob discovered his ritual lair in the hills and brutally killed him.  To make matters worse they buried his corpse in the Southshore cemetery.\n\nSuch disregard for the great wizard is unacceptable.  As his apprentice I shall see to it that the rains of vengeance fall upon the town of Southshore.\n\nWe will need Helcular's Rod first.  Yeti overtook his ritual lair.  Undoubtedly one of the beasts has it.", objectives = "Retrieve Helcular's Rod from the Yeti and bring it back to Novice Thaivand in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[553] = { title = "Helcular's Revenge", description = "Here, take the Rod of Helcular. You will need it.\n\nHelcular fashioned 3 ceremonial pyres as part of his most powerful spell.  The Flame of Azel and the Flame of Veraz lie within the Foothill Caverns. The Flame of Uzel lies in a cave above the caverns, further north in the mountains.\n\nThe Rod of Helcular must be charged from each of the three flames. Once the ritual is complete, drive the rod into Helcular's grave in Southshore, the heavily guarded human town to the south.  Vengeance shall be ours!", objectives = "Charge the Rod of Helcular with the powers of the Flame of Azel, Flame of Veraz and the Flame of Uzel.\n\nDrive the charged rod into Helcular's grave in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[554] = { title = "Stormpike's Deciphering", description = "Prospector Stormpike is a master of decryption and deciphering.  If you take the parchment you found to him, then with luck he can make sense of it.  Stormpike is currently studying in the Prospector headquarters in Ironforge.\n\nAnd when you see him tell him you spoke with me - I've been sending him quite a lot of business lately.", objectives = "Take the Ensorcelled Parchment to Prospector Stormpike in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[555] = { title = "Soothing Turtle Bisque", description = "If there's one thing you'll learn about Southshore it's that we have some of the best cuisine north of Stormwind!\n\nTake my secret recipe for Turtle Bisque, for example. I've known folks to travel from as far as Darkshire just to enjoy a bowl.  Speaking of which, I haven't been able to make any lately.  I used to head up past Dalaran to Lake Lordamere myself to hunt Snapjaws but it's just too dangerous now. If you bring me some Turtle Meat from the Snapjaws up north and Soothing Spices, I'll whip some up!", objectives = "Bring 10 pieces of Turtle Meat and some Soothing Spices to Chef Jessen in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[556] = { title = "Stone Tokens", description = "A notable talent of the wizards of Dalaran is their familiarity with elementals: powerful creatures from other dimensions.  The wizards use magical tokens as a means to control these elementals.  Magus Voidglare would like some of these tokens to study.\n\nEnter the territories of the Dalaran wizards, west of Hillsbrad, and gather the tokens.\n\nYou might find the tokens on any citizen of Dalaran, but I suggest hunting at the internment camp.  It's safer than Dalaran itself.", objectives = "Bring 10 Worn Stone Tokens to Keeper Bel'varil in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[557] = { title = "Bracers of Binding", description = "The Magus will be busy studying those stone tokens you gathered, but I know he'll eventually want examples of their counterpart: bracers of binding.  These are set around the wrists of actual elementals, and bind them into the mage's service.\n\nHunt elementals in the ruins of Dalaran and gather their Bracers of Earth Binding, and the Magus will be pleased.", objectives = "Bring 4 Bracers of Earth Binding to Keeper Bel'varil in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[558] = { title = "Jaina's Autograph", description = "They say that Lady Jaina Proudmoore in Theramore is one of the greatest heroes the Alliance has ever had.  When I grow up, I wanna be a hero of the Alliance too!\n\nDo you know Jaina, $N?  Could you do me a favor, please?  Could you get her autograph for me?  I dunno how to ask her, and she'd probably be too busy for someone like me... but you!  You're an adventurer just like she is!  I bet she'd give you her autograph easy!\n\nPlease?", objectives = "Travel to Theramore to see about getting Lady Jaina Proudmoore's autograph for your ward.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[559] = { title = "Farren's Proof", description = "Would you believe it, $n? Redpath wasn't satisfied with all the murlocs we killed--oh now, don't be modest, you had some hand in it. Now he wants me to bring proof of the dead, hacking off cold, slimy murloc heads to submit for his approval.", objectives = "Collect 10 Murloc Heads from the murlocs on the Western Strand for Lieutenant Farren Orinelle in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[560] = { title = "Farren's Proof", description = "You know, $n, I'd really rather not take these heads... Since you've already got a handle on them, would you mind delivering them to Redpath for me?", objectives = "Deliver the sack of murloc heads to Marshall Redpath in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[561] = { title = "Farren's Proof", description = "Please inform Lieutenant Orinelle that I would like him to refocus his efforts on the naga infesting the Eastern Strand. When he has results, tell him to report to me in person.", objectives = "Speak with Lieutenant Farren Orinelle in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[562] = { title = "Stormwind Ho!", description = "My former mentor in the Stormwind city guard sent a message to me that Alliance High Command is becoming concerned with the threat posed by the naga. From what he's heard, there's good chances for promotion--or at least reassignment--for anyone who proves valuable in this regard.\n\nThere's just one small problem... I can't handle the naga, $n. Oh sure, I could break up a drunken barroom brawl, or haul off a belligerent beggar, but the naga are too much for me. You've got to help me, $n!", objectives = "Kill 10 Daggerspine Shorehunters and 10 Daggerspine Sirens for Lieutenant Farren Orinelle in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[563] = { title = "Reassignment", description = "It shouldn't be a problem getting my report seen. The new captain of the guard, Major Samuelson, was my mentor while I was stationed in Stormwind. It should give him more than enough excuse to have me transferred back to the city. I'll need you to carry my report to him, though... wouldn't want ol' Redpath to catch on.", objectives = "Deliver Farren's report to Major Samuelson in Stormwind Keep.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[564] = { title = "Costly Menace", description = "Ain't nothin' that irks me more than losin' these here beautiful horses.  And believe me, we've lost quite a few between them pesky undead creeps, the dang Syndicate gang and all the other good-for-nothin' scoundrels pokin' about these parts.\n\nBut I swear on my ol' grand-daddy's grave there ain't no bigger menace to our horses here than them Mountain Lions up in Alterac.  Always comin' down from the hills and makin' my life difficult!\n\nYou fancy yourself a hero?  Go and do somethin' about it then!", objectives = "Darren Malvew of Southshore wants you to kill 8 Mountain Lions and 10 Hulking Mountain Lions.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[565] = { title = "Bartolo's Yeti Fur Cloak", description = "I, the great Bartolo, shall make for you the world famous, Alliance renowned, Yeti Fur Cloak!\n\nTravel the planet and find yourself a better cloak, I dare you.  Oh wait, what is that, little $r?  \"Bartolo, there is no finer cloak!\"  Yes, yes!  That, I have heard before.\n\nBartolo requires a Bolt of Wool, a Hillman's Cloak made by a skilled leatherworker, Fine Thread and Yeti Fur, of course!  Bring to me these items and you shall be a happy customer!", objectives = "Bring Bartolo Ginsetti of Southshore a Bolt of Wool, a Hillman's Cloak, Fine Thread and 10 clumps of Yeti Fur.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[566] = { title = "WANTED: Baron Vardus", description = "By order of High Executor Darthalia, the human known as Baron Vardus is wanted for crimes against the Forsaken. Vardus is known to be a high-ranking member of the organization known as the Syndicate.\n\nHe was last spotted in the Uplands in the Alterac Mountains, north of Tarren Mill.\n\nHe is wanted dead. Bring evidence of his demise to High Executor Darthalia to claim the reward.", objectives = "Kill Baron Vardus and deliver his head to High Executor Darthalia in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[567] = { title = "Dangerous!", description = "Dangerous!\n\nThe following humans of Hillsbrad have been deemed dangerous and are marked for bounty by High Executor Darthalia:\n\nClerk Horrace Whitesteed.  Wanted for the murder of Deathguard Toma.\n\nCitizen Wilkes.  Wanted for the murder of Apothecary Eli.\n\nMiner Hackett.  Wanted for the murder of Deathstalker Fry.\n\nFarmer Kalaba.  Wanted for the ambush of supplies from the Undercity.\n\nAll of these enemies are hiding and will be hard to find.  A reward will be granted upon notice of their death.", objectives = "High Executor Darthalia of Tarren Mill is offering a bounty on Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett and Farmer Kalaba.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[568] = { title = "The Defense of Grom'gol", description = "Throm'ka, $c!\n\nYour arrival at Grom'gol is timely, indeed.  As commander of the Warchief's base camp here in the jungle I am bound by honor to ensure the safety of all members of the Horde.  Our mission to provide a safe chain of supply to Stonard is being hampered by some of the local inhabitants.\n\nI am putting you in charge of thinning out the raptor population outside of Grom'gol.  Once you have made significant progress, report back to me for reassignment.", objectives = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 15 Lashtail Raptors.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[569] = { title = "The Defense of Grom'gol", description = "When we first arrived in this jungle we did not intend to wage war on the local tribes.  Our mission to supply Stonard is of the highest priority.  But complications have arisen.  A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol.  Despite warnings, they continue to ambush our supply caravans.\n\nI am putting you in charge of dealing with these uncooperative ogres.\n\nTravel to the ruins and attempt to drive them from the area.  At the very least it will send a firm message.", objectives = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 10 Ogre Brutes and 5 Ogre Witch Doctors.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[570] = { title = "Mok'thardin's Enchantment", description = "The power of the jungle's magic must be realized and then harnessed by the Horde.  My rituals have proven successful so far.  I can cast very powerful enchantments.  For you, brave $c, I shall make a special item indeed.\n\nBring to me some Shadowmaw Panther claws along with a Tigress fang.  Not just any fang will do.  It must be in pristine condition.\n\nThe beasts lurk throughout the jungle but you will find some close by, just across the river from Mizjah Ruins to the southeast.", objectives = "Far Seer Mok'thardin at the Grom'gol base camp wants 8 Shadowmaw Claws and a Pristine Tigress Fang.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[571] = { title = "Mok'thardin's Enchantment", description = "What I need from you now will be very difficult to obtain.\n\nTo hold all these feathers, claws and the pristine fang in place I require a magical tether.  Only an aged gorilla sinew will work.\n\nYou will only be able to find one on an Elder Mistvale Gorilla.  They are known to forage to the east of Booty Bay.\n\nThe sinew must be perfect.  It might take quite a few kills for you to find exactly what I need but it will be well worth the hunt.", objectives = "Bring an Aged Gorilla Sinew to Far Seer Mok'thardin in Grom'gol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[572] = { title = "Mok'thardin's Enchantment", description = "The items you gathered from the feline beasts of the Vale are only the first requirement for a powerful enchanted item.  These jungle trinkets combined with my shamanistic ritual will provide you with a very useful tool in assisting the Horde and the Warchief.\n\nBut now you must gather for me some Jungle Stalker Feathers.  The feathers are traditionally worn by the beasts on their armbands.  You will find a tribe of the raptors directly south of Grom'gol, not far from the great arena.", objectives = "Bring 10 Jungle Stalker Feathers to Far Seer Mok'thardin at the Grom'gol base camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[573] = { title = "Mok'thardin's Enchantment", description = "There is but one final reagent needed to complete the enchantment.\n\nIn the south, towards the western coast, high above the bluffs, lies a Holy Spring.  This spring is the subject of great conflict amongst religious and mystical scholars.  Every race in Azeroth claims that the spring waters were made divine for their people.\n\nMy final request of you: bring to me Holy Spring Water.  Be warned.  An expedition of naga explorers have advanced upon the spring.  They will need to be dealt with as well.", objectives = "Far Seer Mok'thardin of Grom'gol needs Holy Spring Water.  He also wants you to kill 10 Naga Explorers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[574] = { title = "Special Forces", description = "Now that many of his regular troops are reduced, you must face his highly trained forces.  When they're not in the wilderness slaughtering our rebel soldiers, they are found deep in the back of the Kurzen Compound, in a cave they call the Stockpile.\n\nI know many of Kurzen's troops personally, and I know they are skilled, loyal, and cruel.  This is no easy task I set before you, $N.\n\nAfter you defeat them, report to Lieutenant Doren, my commanding officer.  He will want your report firsthand.", objectives = "Kill 10 Kurzen Commandoes and 6 Kurzen Headshrinkers.\n\nReport to Lieutenant Doren at the Rebel Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[575] = { title = "Supply and Demand", description = "\"The finest leathercrafter of the South Seas and the worlds old and new.\" That's what they call me. Me! Drizzlik! The finest lea... Ahem. Well.\n\nMy leather goods are known far and wide as the most exquisite, a connoisseur's choice!\n\nI've just received an order from Director Riddlevox of the Tinkers' Union for a dozen of his favorite Excelsior-line boots. Our best sellers, actually.\n\nTo start on the basic shape, I'll need crocolisk skins from the crocs along the river in northern Stranglethorn.", objectives = "Bring 2 Large River Crocolisk Skins to Drizzlik in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[576] = { title = "Keep An Eye Out", description = "Avast!  Who goes there?\n\nArgh, I am but useless without me special enchanted eye.  Bad enough to have lost me eyes in battle in the first place!  But by some stroke o' luck we docked in Menethil and a traveling wizard enchanted a special glass eye that let me see again.\n\nLast night I ended up gettin' jumped by some Bloodsail Buccaneers on me way out.  Took me eye, they did!  Seems those blokes have found their way to Booty Bay.\n\nHelp an old sea dog out by gettin' me eye back?", objectives = "Dizzy One-Eye in Booty Bay wants you to retrieve his eye from the Bloodsail Buccaneers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[577] = { title = "Some Assembly Required", description = "Well, I've got the basic shape of the boots worked out, and they're coming along fine, but the skins you brought aren't going to be quite enough for the inner layers.\n\n\"What are we going to do, Drizzlik?\" No doubt the question on your lips, and well, isn't it lucky you're talking to Drizzlik, because he's going to tell you what we're going to do!\n\nThe inner layers will never really be seen, so we'll just get some of the thicker, cheaper skins from the crocs around Lake Nazferiti to fill the boots out.", objectives = "Bring 5 Snapjaw Crocolisks Skins to Drizzlik in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[578] = { title = "The Stone of the Tides", description = "If there is indeed a goblin mage and water elementals haunting the island, it could mean the Stone of the Tides can be mine!\n\nI want you to locate this haunted island... find out what's going on. Oh, and if you perhaps want to find out more about the Stone of the Tides, take this scrip to the Stormwind Library, they should be able to find you a copy of the book I first came across the legend in.\n\nCould it be that Gazban actually discovered the Stone...?", objectives = "Find the haunted island for Baron Revilgaz in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[579] = { title = "Stormwind Library", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[580] = { title = "Whiskey Slim's Lost Grog", description = "We was splicin' the mainbrace somethin' fierce off of the Overlook Cliffs, ol' Hinterlands just in the distance.  Thought the seas was goin' to swallow us whole.\n\nOl' Slim knows all about liquid courage!  Cap'n had a crate of Pupellyverbos Port we commandeered from a privateer en route to Stormwind.\n\nSo when that storm off of Hinterlands hit, I busted into the grog.  Big wave hit and tossed them bottles overboard.  Cap'n is goin' to give me a taste o' the cat if ye don't help me get 'em back though!", objectives = "Whiskey Slim in Booty Bay wants you to bring him the bottles of Pupellyverbos Port he lost.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[581] = { title = "Hunt for Yenniku", description = "A doom, there is.  A doom on my chief's youngest son, Yenniku.  As is a custom with our people, he was given to the Gurubashi Trolls of Zul'Gurub, but after my tribe, the Darkspear tribe, left with the orc Thrall, poor Yenniku was lost to us.  I was sent from distant Orgrimmar, back to Stranglethorn, to search for my chief's son.\n\nAnd I believe the Bloodscalp tribe has him.\n\nIf you would help me, then hunt the Bloodscalps.  You may find them to the north.  Gather their tusks and return to me.", objectives = "Bring 9 Bloodscalp Tusks to Nimboya at the Grom'gol Base Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[582] = { title = "Headhunting", description = "We must find if Yenniku is dead.\n\nSlay the Bloodscalp Headhunters and take from them their Shrunken Heads.  You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them.\n\nAnd if Yenniku was killed by the Bloodscalps, then may a 600-year curse fall on the spirit of their chief, Gan'zulah!\n\nGo, $N.  You may find many Headhunters at the ruins of Zuuldaia and Zul'Kunda, along the coast to the north.", objectives = "Bring 20 Shrunken Heads to Nimboya at the Grom'gol Base Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[583] = { title = "Welcome to the Jungle", description = "Welcome to Stranglethorn!\n\nPerhaps you're not aware of this, but that dwarf over there is the one and only Hemet Nesingwary, renowned war hero of the Alliance and master big game hunter.  He's not one for welcoming strangers into his camp, but you look like you've seen quite a bit of action in your day, $c.\n\nBeing a veteran of many battles himself, Master Nesingwary has a soft spot for fellow heroes.\n\nGo and speak with him.  Perhaps he can give you some hunting pointers.", objectives = "Speak with Hemet Nesingwary.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[584] = { title = "Bloodscalp Clan Heads", description = "Yenniku was not among the heads, and I thank the Great Serpent for it.  But we are no closer to finding him.\n\nWe must know the truth, and I fear that only the Bloodscalp chief and his witchdoctor know it.  They are the enemies of the Darkspear tribe and will not speak freely, so we must force the truth from their dead lips!\n\nBring me the heads of Gan'zulah and Nezzliok the Dire and place them within this cauldron.\n\nThey are deep within Zul'Kunda.  Bring their heads...we will then make them talk.", objectives = "Bring Gan'zulah's Head and Nezzliok's Head to the bubbling cauldron at the Grom'gol Base Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[585] = { title = "Speaking with Nezzliok", description = "<The head of Nezzliok speaks.>\n\nIt is true.  I know where the child of the Darkspears was taken.  You have bested me and bound my spirit, but I will say nothing without appeasement!\n\nThe Bloodscalps war with the Skullsplitters.  To gain my favor, steal from the Skullsplitters 3 of their trophy skulls and place them here with us, so that my spirit will have slaves in the Nether.  One skull must be from their trophy pile in Balia'mah, another from Ziata'jai, and the last from Zul'Mamwe.", objectives = "Bring a Balia'mah Trophy, a Ziata'jai Trophy and a Zul'Mamwe Trophy to the Bubbling Cauldron at the Grom'gol Base Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[586] = { title = "Speaking with Gan'zulah", description = "<The head of Gan'zulah speaks.>\n\nCurse you!  And curse your ancestors!!\n\nOnly blood and revenge can cool my rage, so if that is your wish, then... do this:\n\nThrow yourself into the heart of the Skullsplitters to the east.  Slay the fiercest among them, and if you survive...then break yourself against their chief, Ana'thek the Cruel.  Hah!  Bring me his shattered armor if you can!\n\nMay he tear off your limbs and leave you to rot and be eaten by carrion.", objectives = "Kill 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters, and 4 Skullsplitter Berserkers.\n\nBring the Broken Armor of Ana'thek to the Bubbling Cauldron at the Grom'gol Base Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[587] = { title = "Up to Snuff", description = "Ah, the sea life.  I ain't gonna say it's the good life, but it's my life.\n\nWhen I get into port I like to find me a good bottle of grog and some high quality snuff.  Nasty habits but what's a pirate without his vices, right?\n\nSo you can imagine how heartbroken I was to find out the herbalist here in town has gone and sold out of the stuff.  Says his shipment got hijacked by those damned Bloodsail Raiders.\n\nI bet a fearless $c like you could convince 'em to share the goods, eh?", objectives = "Deeg in Booty Bay wants you to bring him 15 shares of Snuff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[588] = { title = "The Fate of Yenniku", description = "<Nezzliok speaks.>\n\nYou have appeased myself and my chief, so I will tell you that which you seek to discover...\n\nYoung Yenniku is lost to his clan.\n\nHe was taken by the witchdoctor Zanzil the Outcast.  Now Zanzil controls him, body and soul, and only the most potent magic could set him free.\n\nA magic that you do not have, $c.\n\nPerhaps your Darkspear allies can offer a hope of Yenniku's salvation.  But that, I doubt.", objectives = "Speak with Kin'weelay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[589] = { title = "The Singing Crystals", description = "Legends tell of a jewel, hidden deep in the heart of Stranglethorn.  We call it the Mind's Eye, and it has great powers.  If you gain this Eye then, perhaps, we can use it to bring lost Yenniku back from the darkness.\n\nI will consult with the spirits of the jungle to find the Mind's Eye.  While I do this, you enter the Crystalvein Mine, southeast of here, and gather Pulsing Blue Shards from Ironjaw Basilisks.  The shards are rare, but we will need their magic to bend the Mind's Eye to our will.", objectives = "Bring 3 Pulsing Blue Shards to Kin'weelay at the Grom'gol Base Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[590] = { title = "A Rogue's Deal", description = "What?\n\nWhat?!\n\nYou want money? I don't owe you any money.\n\nLetter? What letter? Oh, you wanna fight then? All right, mate... let's do this! Owe you any money...", objectives = "Defeat Calvin Montague in Deathknell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[591] = { title = "The Mind's Eye", description = "The Mind's Eye is held by an ogre mage, east of here and deep within the Mosh'Ogg ogre mound.  His name is Mai'Zoth.  I know him from when the Darkspears dwelt in Stranglethorn - he is vicious, and his magic is strong.\n\nAnd if he has the Mind's Eye, then his magic will be stronger still.\n\nYou must face Mai'Zoth and wrest from him the Mind's Eye.  It is a perilous task, but it is the only hope we have of saving Yenniku.", objectives = "Bring the Mind's Eye to Kin'weelay at the Grom'gol Base Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[592] = { title = "Saving Yenniku", description = "I have reshaped the Mind's Eye into a Soul Gem.  Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul.\n\nThen, bring the gem to Nimboya.\n\nYenniku dwells with Zanzil the Outcast, at the Ruins of Aboraz, along the Crystal Shore on the distant Cape of Stranglethorn.", objectives = "Bring the Filled Soul Gem to Nimboya.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[593] = { title = "Filling the Soul Gem", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[594] = { title = "Message in a Bottle", description = "The note reads, in fairly good handwriting:\n\nTo any that can aid me-\n\nPlease, my need for help is dire. A great Skymane holds me captive on an island in the South Seas.\n\nThe stars at night are foreign to me and obscured by the jungle trees, but on the clearest days I see Wild Shore to the northwest, and what seem to be large sailing ships to the southwest.\n\nI beg of you, my would-be savior, please help me.", objectives = "Find the author of the message in a bottle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[595] = { title = "The Bloodsail Buccaneers", description = "You sure seem eager to work, matey.  Not sure why some land-loving $r $c is offering help to the Blackwater Raiders, but I'm not going to turn you away.\n\nOur ship just docked here in Booty Bay and word has it that our rivals--those damned, dirty Bloodsail Buccaneers--have been spotted all over southern Stranglethorn.\n\nAll the boys are too busy hitting the grog and looking for ladies!  What I need is a scout.\n\nCheck the cove just north of Booty Bay along the Savage Coast and see what you find.", objectives = "First Mate Crazz wants you to check the cove north of Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[596] = { title = "Bloody Bone Necklaces", description = "I was sent to Grom'gol  to aid Nimboya on his quest, but... I too have reasons for being here.\n\nThe Bloodscalp tribe is enemy to our tribe.  Collecting trophies of our enemies gives us power over them.  You may aid our tribe by hunting our enemies.\n\nThey dwell to the north.  Slay Bloodscalp trolls and take from them their bloody bone necklaces.  Collect many, and your reward will be great.", objectives = "Bring 25 Bloody Bone Necklaces to Kin'weelay at the Grom'gol Base Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[597] = { title = "The Bloodsail Buccaneers", description = "The map shows Booty Bay with a red \"X\" drawn precisely at the spot at which you are standing.\n\nThe scribbled text reads:\n\n\"You men are to secure a camp at this location and keep quiet.  Wait for the signal from the southern command post before attacking.  If anyone approaches you, kill them.\"", objectives = "Report your findings to First Mate Crazz in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[598] = { title = "Split Bone Necklace", description = "Now that you have gathered Bloodscalp trophies, I have another task for you.  The Skullsplitter tribe of trolls live to the southeast, and for years we have warred with them.  Although the Darkspears no longer dwell in Stranglethorn, we are bound to our conflict with the Skullsplitters.\n\nSo, hunt them.  Gather their Split Bone Necklaces and return to me.  Aid us in our war, and you will earn the friendship of the Darkspears.", objectives = "Bring 25 Split Bone Necklaces to Kin'weelay at the Grom'gol Base camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[599] = { title = "The Bloodsail Buccaneers", description = "Shiver me timbers!  So the Bloodsail Buccaneers are planning some sort of attack on Booty Bay?  Why, the nerve of those scoundrels.  Booty Bay will always be run by the Blackwater Raiders!\n\nThis is bigger than I thought.  Report what you have learned to Fleet Master Seahorn at once!  The ol' sea dog is around town somewhere....", objectives = "Report the planned Bloodsail attack to Fleet Master Seahorn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[600] = { title = "Venture Company Mining", description = "The Venture Company has a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold!  Please, you must help me!\n\nThe Venture Company is mining near the Crystalvein Mine to the north.  They can't get into the mine because of all the basilisks, but they're still able to dig up Singing Crystals from the surrounding hills.\n\nTake their crystals from them, and show them they don't have the run of the jungle.\n\nAnd... um... bring me those crystals as proof!", objectives = "Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[601] = { title = "Water Elementals", description = "The water elementals were no doubt summoned by Gazban, the goblin wizard rumored to have discovered the Stone of the Tides. As you may know, the Stone of the Tides curses its bearer, causing him to fade in and out of existence...\n\nPerhaps we can find a way to counteract the curse. We can have a mage of Dalaran analyze the magical residue of one of the water elemental's bracers. I need you to go back to the island and retrieve a few specimens.", objectives = "Acquire 6 Water Elemental Bracers for Baron Revilgaz in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[602] = { title = "Magical Analysis", description = "From what I've heard, the mages of Dalaran are busy with the reconstruction of their destroyed city, I'm sure you can find one of them who will spare some time to look at the bracers. If there's anything I know about mages, they can't resist a magical puzzle.\n\nTake the bag of water elemental bracers and see if they can shed any light on the Stone's curse.  Look for the Archmage Ansirem Runeweaver in particular.  I've dealt with him before, and his knowledge is vast.", objectives = "Bring the water elemental bracers to Archmage Ansirem Runeweaver in Dalaran.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[603] = { title = "Ansirem's Key", description = "The mage that is in possession of the Stone is amplifying its power through some focal point... an altar of some sort. You should be able to disrupt it by overpowering it.\n\nAs it happens, I know just the thing: an ancient dagger, another troll relic. There's just one... little problem.\n\nYou see, I found the dagger while researching in Stranglethorn, but I gave it to my willful daughter, Catelyn, who ran off to Booty Bay to become a pirate.", objectives = "Talk to Catelyn in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[604] = { title = "The Bloodsail Buccaneers", description = "Crazz speaks highly of your dedication to the Blackwater Raiders.  I am going to trust you with a mission of extreme importance to the fleet.\n\nInfiltrate the so-called southern command post the Bloodsail Buccaneers have established on the Wild Shore.  Raid the encampment.  Bring me their charts along with their written orders.  We shall see exactly what those scum are up to.", objectives = "Fleet Master Seahorn in Booty Bay wants you to kill 10 Bloodsail Swashbucklers and bring back the Bloodsail Charts and the Bloodsail Orders.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[605] = { title = "Singing Blue Shards", description = "The Singing Crystals are unique to Stranglethorn, and are very valuable to certain parties.  I can move those crystals, but the cursed Venture Company makes it hard for an honest entrepreneur like myself to gather any!\n\nI'd like to hire you.\n\nThe basilisks in Stranglethorn eat the crystal.  This gives them their hardened skin, and sometimes decent quality crystal can be harvested from it.\n\nYou can get it from any basilisk, but the less nasty ones are along the shores south of Zul'Kunda, to the north.", objectives = "Bring 10 Singing Crystal Shards to Crank Fizzlebub.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[606] = { title = "Scaring Shaky", description = "If there's one thing I can't stand, it's people who don't pay their gambling debts!  And there are a lot of people who owe me. Think you can help me collect?\n\nFirst, there's \"Shaky\" Phillipe down by the docks.  He owes me plenty after last week's game and I want my due!  But to get it, we'll have to scare him.\n\nGo out of town and hunt Elder Mistvale Gorillas.  Find a nice selection of giblets, then take them to Shaky.  Don't let on that they're from an animal; let him think the worst.", objectives = "Bring 5 Mistvale Giblets to \"Shaky\" Phillipe in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[607] = { title = "Return to MacKinley", description = "Here, take this pouch and give it to Sea Wolf.  And tell him I meant to pay him back!  I swear!!\n\nI just got a little drunk and lost my way, and...you know how things are.  He'll understand - you don't have to get rough!", objectives = "Bring Shaky's Payment to \"Sea Wolf\" MacKinley", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[608] = { title = "The Bloodsail Buccaneers", description = "Blast the nerve of Firallon!  He couldn't sail a skiff through Crystal Lake let alone lead an entire fleet against us.\n\nThe Bloodsail Buccaneers will pay for their carelessness.  Now that we know their plan of attack, we can counter before they know what hit them.\n\nBut why send the entire fleet to do the work of one brave adventuring party?  $n, take some of your most skilled comrades out to Firallon's landing spot and assassinate the Bloodsail leadership.  Their fleet will sink soon after....", objectives = "Fleet-Master Seahorn in Booty Bay wants you to kill Captain Stillwater, Captain Keelhaul and Fleet Master Firallon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[609] = { title = "Voodoo Dues", description = "My list is shortening, but there are still people who owe me.\n\nNext, we have Maury \"Club Foot\" Wilkins, Jon-Jon the Crow, and Chucky \"Ten Thumbs.\"\n\nThese scurvy dogs' debts are months outstanding and I thought they skipped town to avoid paying up!  Later, I heard they're cursed and bewitched and now wander the jungle ruins.  But I don't care what their fate is - I want what's mine!\n\nThey're at the Ruins of Aboraz and the Ruins of Jubuwal, northeast of here.  Find them, and collect.", objectives = "Bring Maury's Clubbed Foot, Jon-Jon's Golden Spyglass, and Chucky's Huge Ring to \"Sea Wolf\" MacKinley in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[610] = { title = "\"Pretty Boy\" Duncan", description = "My FATHER sent you? I'd have thought that old codger would have given up on me by now.\n\nIt wasn't really his fault I ran off, he just shouldn't have expected I'd be willing to live a boring life, reading over musty books and associating with grey-haired, stiff-backed, stuffy mages!\n\nIf you need my dagger, you'll have to get it back from \"Pretty Boy\" Duncan, one of the Bloodsail Buccaneers. Put something 'tween his shoulders and I'm sure he'll give it up.", objectives = "Get Catelyn's dagger from \"Pretty Boy\" Duncan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[611] = { title = "The Curse of the Tides", description = "So you're looking for an altar of some sort? Well, I'm no expert on troll ruins like my father, but I have heard about a sunken troll city out near that island you're looking for. Maybe you should try there.\n\nYou got my knife back for me, so I guess you can borrow it... but I want it back when you're done!", objectives = "Destroy the Altar of the Tides with Catelyn's Blade, kill Gazban and bring the Stone of the Tides and Catelyn's Blade back to Baron Revilgaz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[613] = { title = "Cracking Maury's Foot", description = "Curses!  That swab Maury put a lock on his foot, and I can't open it!  His loot's inside the foot, and that's what he owes me!\n\nWe need to find the key to open the lock.  Maury was known to gamble with the Mosh'Ogg ogres, at their mound to the northeast.  And he told me, when he was still alive, that the last time he went to the mound he was chased off after winning too much.  Maybe the Ogres there have his key.\n\nBut if they do, you might have to kill a load of them to find the right one...", objectives = "Bring Maury's Key to \"Sea Wolf\" Mackinley in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[614] = { title = "The Captain's Chest", description = "I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  And one of the giants, Gorlash, stole my Captain's Chest.  He said he wanted it for a snuffbox.  The nerve!\n\nI hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.", objectives = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[615] = { title = "The Captain's Cutlass", description = "After I lost my first ship to those giants, I bought another.  Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains.  I found them, but...they beat me.  They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.\n\nThis time another of the giants, Negolash, stole my cutlass.\n\nFace Negolash and bring me my cutlass!\n\nSpeak with Sprogger.  He was my cook on the Smotts' Revenge, and survived the last attack.  He can help you find the giant.", objectives = "Speak with Sprogger.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[616] = { title = "The Haunted Isle", description = "Baron Revilgaz has had me keep an ear out for rumors of the strange and out-of-place in Booty Bay and Stranglethorn. I don't usually put much stock in ghost stories, but I heard some sailors in the tavern talking about a haunted island off the coast. Water elementals and a raving goblin ghost, they say.\n\nIf you're going to go talk to Revilgaz, could you relay that story to him?", objectives = "Speak with Baron Revilgaz in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[617] = { title = "Akiris by the Bundle", description = "You looking fer work, $N? I might have some if you're up for a little challenge.\n\nI got a friend named Groy who makes a killing selling what the naga call akiris reed: it's some kind of valuable ocean reed. Not too sure what it's for, but he pays well for bundles of the stuff.\n\nYa bring me ten stalks of the stuff, and we'll have business to do. The naga were last seen along the beach to the north of here.", objectives = "Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[618] = { title = "Facing Negolash", description = "Negolash is a hungry giant.\n\nWhen the giants destroyed our ship, Negolash went straight for my kitchen.  He wasn't hungry for crew like the other giants.  Negolash wanted wine...and my Barbecued Buzzard Wings.  They're my specialty, and I had to go all the way to the Badlands for the recipe!\n\nIf you want to lure the giant, then get some wine and a heap of buzzard wings.  Put them in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come for sure!", objectives = "Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.\n\nKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[619] = { title = "Enticing Negolash", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[621] = { title = "Zanzil's Secret", description = "Zanzil the Outcast dwells with his followers in the Jubuwai and Aboraz Ruins, northeast of Booty Bay.  He is exiled from his tribe.  Why? Well...\n\nZanzil has methods of bending the minds of others, and his leaders fear him.  He uses a mixture of jungle plants on his followers to suppress their will and strengthen their bodies.\n\nHis mixture would be worth much to those who wish to control others.\n\nBring me samples of his mixture, and I will find a use for them.", objectives = "Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[622] = { title = "Return to Corporal Kaleb", description = "While you were gone I fixed the pot you brought me.  I even added an extra steam whistle, and look!  There's a new chopper at the bottom that'll cut through leg bones!\n\nYes yes, Krazek's Crock Pot is a 100% cook pleaser!  I'm sure its owner will be satisfied.", objectives = "Bring Krazek's Fixed Pot to Corporal Kaleb at the Rebel Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[623] = { title = "Akiris by the Bundle", description = "$N, since I have you here, I got a message from Groy while you were gone. He mentioned bein' satisfied with the last shipment that arrived and has a client that wants some more of the stuff right away.\n\nI won't be headin' to Theramore for a week, but if you're willin' to make the journey, there's no reason you can't take the stuff for me.\n\nFeeling adventurous? You do know where Dustwallow Marsh is, doncha? I'd be careful though, Theramore can be dangerous if you're the wrong kind of crowd.", objectives = "Bring a Bundle of Akiris Reeds to Privateer Groy in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[624] = { title = "Cortello's Riddle", description = "There is an ornate, well-traveled bridge\nEast of Deadwind and south of Redridge\nUnderneath there waits something for you\nSome call it a hint, others a clue\nThere it will lie for endless tomorrows\nBiding its time in the Swamp of Sorrows", objectives = "Solve the riddle!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[625] = { title = "Cortello's Riddle", description = "A far off land in Kalimdor awaits\nWhere peril has dashed hopes and fates\nEast of Barrens the weather is harsh\nGloom and danger pock Dustwallow Marsh\nBut there lies a clue for those up to the test\nWaiting to be found in a cave in the southwest", objectives = "Solve the riddle!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[626] = { title = "Cortello's Riddle", description = "To Lordaeron! The great land of turmoil\nWhere brave soldiers with death do toil\nFind your way through the great unrest\nThere you will find the end to this quest\nAlong the coast of the Hinterlands, at the base of the great falls\nUnderneath the water there does your treasure call!", objectives = "Solve the riddle!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[627] = { title = "Favor for Krazek", description = "There is a mountain cave in Drywhisker Gorge, far to the north in the Arathi Highlands.  In that cave is rare ore: bloodstone.  The bloodstone in this cave is not of the highest grade, but even low-quality bloodstone is valuable... to those with the knowledge to use it.\n\nI would like some.\n\nI will fix your crock pot, but while I work on it... bring me samples of bloodstone.  Bring me enough, and I'll even give you a bonus.\n\nOh, and if you don't have the skill to mine it... find someone who does!", objectives = "Bring 4 loads of Lesser Bloodstone Ore to Krazek in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[628] = { title = "Excelsior", description = "With the inside finished, all that's left is to add the outer layer. For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line.\n\nIt's hard to find that perfect skin though, the only one that fits my plan is the skin of an elder saltwater crocolisk. The elders only come out to defend the other saltwater crocs, so you might need to kill a few to draw one out.", objectives = "Bring an Elder Crocolisk Skin to Drizzlik in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[629] = { title = "The Vile Reef", description = "Long ago, a great shudder of the earth sunk an old troll city beneath the waters of the Savage Coast to the northwest.  We call that place the Vile Reef, for murlocs now reside in the ruins of the city, attacking any who draw close.\n\nThere is an old tablet among those ruins that tells the ancient tale of Gri'lek, a hero of troll legends.  The tale is sacred to the Darkspear tribe, and although the tablet is too large to move, I want a shard of it to enshrine in our new home in Orgrimmar.", objectives = "Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[630] = { title = "Message in a Bottle", description = "$N, I put my faith in you and anyone you can muster to help free me. The great Skymane King Mukla is my captor. He commands the beasts of this island, and they keep me here against my will with the aid of this chain. If you can slay him and find the key to this shackle, I shall be indebted to you greatly.\n\nI often hear him to the southeast side of the island, but please be careful: he is not to be trifled with.", objectives = "Slay King Mukla and return to Princess Poobah with the Key to free her.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[631] = { title = "The Thandol Span", description = "A tremendous explosion roared through the hills.  'Twas horrible, I tell you!\n\nGood soldiers died defending the Thandol Span.  Longbraid says we'll take revenge on the Dark Irons before all is said and done.\n\nWe're in a world of hurt though and I don't see any reinforcements in sight.  Longbraid sent Ol' Rustlocke to scout the eastern bridge to see if we could secure it.\n\nThat was days ago.  We haven't the manpower to search for him with Dun Modr under siege.\n\nPerhaps you can find him...", objectives = "Rhag Garmason wants you to locate Ol' Rustlocke.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[632] = { title = "The Thandol Span", description = "It seems as though poor Ol' Rustlocke ran into a Dark Iron ambush.  You notice a parchment next to his clenched fist.\n\nReport the grim news to Rhag Garmason and show him what you found.", objectives = "Report back to Rhag Garmason and show him the parchment you found on Rustlocke's corpse.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[633] = { title = "The Thandol Span", description = "Heavens no!  Poor Rustlocke.  'Tis quite a tragedy indeed.\n\nWe must not let his death pass in vain.  This parchment you discovered indicates that Kam Deepfury, the mastermind behind the original attack, arranged for a cache of explosives to be stashed just across the Thandol Span, in Arathi Highlands.\n\nIf those explosives make it to the bridge, our major supply line to the north will be severed!  The cache must be destroyed, $n!  Return to me when your mission is complete.\n\nYou're our only hope.", objectives = "Destroy the cache of explosives.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[634] = { title = "Plea To The Alliance", description = "I ask of you one more small favor, $c.  We await the reserves of Ironforge.  However, Roggo has knowledge of an Alliance camp to the north in Arathi Highlands at Refuge Pointe.\n\nTravel there and seek out Captain Nials.  Ask the good Captain if the Alliance can spare some soldiers to help us reclaim Dun Modr and the Thandol Span.", objectives = "Seek out Captain Nials at Refuge Pointe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[635] = { title = "Crystal in the Mountains", description = "This shard pulses as you hold it...\n\nYou feel a sense of pleading coming from the shard, as if someone is trying to communicate, someone who desperately needs your help.\n\nA vision appears in your mind - of the northern mountains of Arathi, and of a brilliant crystal jutting from the earth there.\n\nYou feel drawn to that place.", objectives = "Find the crystal from your vision.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[636] = { title = "Legends of the Earth <NYI>", description = "This book tells the tale of an elemental princess, Myzrael, and of her imprisonment deep underneath the Arathi Highlands.\n\nIt also tells of a secret outcropping of crystals in the highlands.  These crystals, the Shards of Myzrael, are a window to the princess' prison.\n\nIf a brave soul found the Shards of Myzrael, the perhaps $ghe:she; could speak with her...", objectives = "Find the Shards of Myzrael.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[637] = { title = "Sully Balloo's Letter", description = "The waterlogged and war-torn envelope dissolves in your hands, leaving you with a few pages of a letter in your grasp, written with painstaking care.\n\nThe letter is addressed to a Mrs. Sara Balloo of Ironforge and begins, \"My dear Sara....\"", objectives = "Deliver Sully Balloo's Letter to Sara Balloo.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[638] = { title = "Trollbane", description = "With Thoras Trollbane dead and Stromgarde in ruins, Vol'jin has instructed that we make every effort to spirit the legendary sword Trol'kalar from the humans' hands, so that we might use it in our coming battles against the trolls of Zul'Gurub.\n\nZengu, one of our seasoned hunters, was dispatched to Hammerfall in northeastern Arathi Highlands to oversee its procurement.", objectives = "Travel to Hammerfall in the Arathi Highlands and speak with Zengu.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[639] = { title = "Sigil of Strom", description = "In ancient times, trolls fought against the Arathorian Empire and our most capable adversary, Lord Ignaeus of Strom, named Trollbane. He rode into battle wielding Trol'kalar--troll slayer, in their ancient tongue.\n\nBut now the sons of Trollbane are weakened, their stronghold brought to ruin.\n\nThe sword is protected by several sigils that were divided among the survivors of Stromgarde, and we must retrieve them.\n\nThe first was taken by the Syndicate, one of their men in Stromgarde should have it.", objectives = "Get the Sigil of Strom for Zengu in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[640] = { title = "The Broken Sigil", description = "Thoras Trollbane's tomb is protected by three sigils--the first of which you retrieved from the Syndicate. The other two will be harder to get, as they're held by the firmly entrenched Stromgarde militia.\n\nThe sigil of Thoradin was divided into eleven pieces by Thoras' son, Galen, and dispersed among the Stromgarde defenders. Retrieve the pieces and bring them to Tor'gan, the troll shaman, he will be able to bind them into the complete sigil.", objectives = "Retrieve the 11 Sigil Fragments from the defenders in Stromgarde, and bring them to Tor'gan in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[641] = { title = "Sigil of Thoradin", description = "The reconstruction worked flawlessly. The sigil can now be used to unlock the seal on Trollbane's tomb. Return it to Zengu, no doubt he has additional tasks for you to complete.", objectives = "Bring the restored Sigil of Thoradin to Zengu in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[642] = { title = "The Princess Trapped", description = "My name is Myzrael.  I am a princess of the earth, and my captors, the giants, have trapped me deep beneath the Arathi Highlands.  These crystal shards are the only way I can speak with the surface world.\n\nPlease help me.  Allies of the giants, the Drywhisker Kobolds, have a shard like this one in their Drywhisker Gorge, to the east.  To power the cluster, you must gather Motes of Myzrael from the kobolds and apply them to it.\n\nI beg you, $N, aid me!", objectives = "Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[643] = { title = "Sigil of Arathor", description = "Though they can barely be said to control Stromgarde, let alone the whole of Arathi Highlands, the human prince trots the remnants of his cavalry over the countryside. I can't understand why he does it, but who understands the way the humans think, hm?\n\nWhatever his reasoning, more importantly, he has given one of the sigils to Lieutenant Valorcall, their cavalry leader. Locate him and bring his sigil back to me.", objectives = "Retrieve the Sigil of Arathor and return it to Zengu in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[644] = { title = "Sigil of Trollbane", description = "The final of the sigils needed to unlock the tomb of Thoras Trollbane is held by his son personally. He resides deep within Stromgarde, in a chapel in the militia-held districts. Prince Galen is well protected and no slouch of a warrior himself, so this task could prove most difficult.", objectives = "Kill Prince Galen Trollbane and bring the Sigil of Trollbane to Zengu in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[645] = { title = "Trol'kalar", description = "What's this? With the four sigils brought together, they have formed together to create one sigil. There can be no doubt that this will be able to break the wardings placed upon Trollbane's tomb.\n\nTrollbane's remains are entombed in the Sanctum behind the chapel in Stromgarde. Retrieve Trol'kalar.", objectives = "Retrieve Trol'kalar from Trollbane's tomb in Stromgarde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[646] = { title = "Trol'kalar", description = "The light slowly fades, the sword Trol'kalar, held within a stone sheath has been released.", objectives = "Deliver Trol'kalar to Zengu in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[647] = { title = "MacKreel's Moonshine", description = "Had quite a bit of the ol' Moonshine last night!  Longbraid would have my head if he knew that I passed out during my watch.\n\nThe noggin hurts something fierce.  Felt as though a whole brigade of siege engines passed overhead, all that rumbling.\n\nOh my, look at the time! I promised Brewmeister Bilger in Southshore that I'd repay my debt to him by sending some Moonshine.\n\nBut there are just 15 minutes left before I'm overdue!  Take him this batch, would you please?  And hurry!", objectives = "Take MacKreel's Moonshine to Brewmeister Bilger in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[648] = { title = "Rescue OOX-17/TN!", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-17/TN to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  I need you to escort the robot from its current location to, let's say, Steamwheedle Port!  That should be a perfect place, and long enough, to get things on line!\"\n\n\"Escort it safely to the port, and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", objectives = "Escort OOX-17/TN to Steamwheedle Port, then report to Oglethorpe Obnoticus in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[649] = { title = "Ripple Recovery", description = "I've got some salvage work for you, and if you're an aficionado of fine ripple like I am, then you'll love this task.  Ripple!\n\nIt's a drink, you dummy.\n\nAn abandoned Horde outpost has a stash of Hinterlands Honey Ripple from when they were in business.  You can't get fine ripple like that anymore!  One of Malton's dummy associates knows the shot, so you'll go out there and bring me a case of packaged ripple, and two for my own collection!  Talk to Malton, he'll fill you in on the details.", objectives = "Talk to Malton Droffers in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[650] = { title = "Ripple Recovery", description = "The elf you will need to talk to is Gilveradin Sunchaser.  He can name any wine, vintage and all, just by smell alone!  He can package up the ripple we need, so you'll need to talk with him.  We need six bottles for packaging, two for dad, and how ever many he'll want... and believe me, he'll want some.  When you've packaged the ripple and got dad's two bottles, come back here!\n\nGilveradin's camp is near some high elf lodge in the Hinterlands, and those high elves are not good.  Trust me.", objectives = "Talk to Gilveradin Sunchaser; his camp is located in the Hinterlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[651] = { title = "Stones of Binding", description = "Four Stones of Binding are scattered throughout Arathi.  These stones keep me pinned beneath the earth.\n\nTo unlock them you must unlock the strongest: the Stone of Inner Binding.  And to do that, you must gather keys from the other three.\n\nThese stones are watched by guardians, but if you are clever, or lucky, you may find ways to banish them.", objectives = "Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.\n\nBring them to the Stone of Inner Binding.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[652] = { title = "Breaking the Keystone", description = "Opening the Stones of Binding loosened much of my confinement, but a lock still holds me chained.  It is the Keystone you see among this circle of stones.  And the key is held by one of my captors, the stone watcher Fozruk.\n\nYou must obtain that key, which the stone watchers call the Rod of Order, from Fozruk and use it to open the Keystone.\n\n$N, you have done so much to aid me.  Just a little more...and my gratitude will shake the very foundations of the earth!", objectives = "Find and kill Fozruk.  Bring the Rod of Order to the Keystone in the Arathi Highlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[653] = { title = "Myzrael's Allies", description = "<Myzrael speaks.>\n\nFree!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me.\n\nBut in time I will confront the giants, and they will regret their wardship of me!\n\nYou are a noble ally, $N.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface.\n\nSpeak with Gerrig Bonegrip.  He is in Ironforge, in a shop of the Forlorn Cavern.  He knows how I can be summoned.", objectives = "Speak with Gerrig Bonegrip in the Forlorn Cavern of Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[654] = { title = "Tanaris Field Sampling", description = "Activating the power source makes the field testing kit start to glow and vibrate.  It would seem to be working as planned.\n\nAccording to Chief Engineer Bilgewhizzle, you now have two hours to collect the data you need in the Tanaris desert.  If you do not collect it within two hours, all the data will be lost and you will need to buy another power source from him.\n\nReturn to him when you have completed the task.", objectives = "Acquire acceptable samples for 8 basilisks, 8 hyenas, and 8 scorpions.  Bring the testing kit back to Chief Engineer Bilgewhizzle in Gadgetzan before the power source runs out.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[655] = { title = "Hammerfall", description = "It is still clear to me, like yesterday... So many years without hope, with wood and steel to bind me to this terrible place. Then finally, finally! There was the Warchief. Doomhammer in his midnight plate, his warhammer held high.\n\nIt was... too terrible... That the blow of a coward would strike down our greatest hero. From behind he charged on his horse, and then his lance ran him through... I fell to my knees. What hope was there? What hope is there...", objectives = "Speak with Tor'gan in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[656] = { title = "Summoning the Princess", description = "You must defeat Myzrael before she grows in strength.  If you do not, then once she has gathered enough power she will challenge her captors!  There are some who think they can control her, but if she can be controlled then why did the giants chain her in the first place??\n\nCrazy logic, eh?\n\nTo defeat her, summon her at the Shards of Myzrael where you first spoke with her.  Defeat her and gather her Eldritch Shackles, then bind them to the Shards of Myzrael.\n\nDo that, and she will again be trapped.", objectives = "Go to the Shards of Myzrael, summon her and defeat her.\n\nGather her Eldritch Shackles and bind them to the Shards of Myzrael.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[657] = { title = "Hints of a New Plague?", description = "<Quae begins to go through the folder.>\n\nThis IS interesting. Seems Apothecary Jorell has been working on some deadly experiments here at Go'Shek. Not sure what that has to do with Hillsbrad, but Phin wouldn't like it if we let it continue.\n\nWe had a run-in with some orcs while you were gone, and I'm not in good enough shape to help Kinelory. If you're up for it, she's going to need some protection when she goes down to the farm to steal whatever research Jorell still hasn't sent to Tarren Mill.", objectives = "Speak to Kinelory.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[658] = { title = "Hints of a New Plague?", description = "So, Phin sent you to check on us? Not surprised--he worries too much.\n\nWe've been watching the farm for days, and Kin claims she saw a courier come out of that small house to the south not long ago.\n\nShe talks a lot, but I can always trust her senses when we're in dangerous areas.\n\nYou wouldn't happen to be a skilled tracker, would you? We think the courier might be carrying notes to Tarren Mill. If we could get our hands on those documents, it might shed some light on what's happening in Hillsbrad.", objectives = "Find the Forsaken Courier and bring back her Sealed Folder to Quae near the Go'Shek Farm.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[659] = { title = "Hints of a New Plague?", description = "Hail, and well met, $N. I lead a group of adventurers investigating odd happenings in this area.\n\nMy cousin in Hillsbrad recently put down his dog Stanley because the animal mystically grew to an immense size and savagely attacked anyone who came near him.\n\nI believe the undead are involved, and we're looking for signs to prove as much.\n\nTwo of my companions, Quae and Kinelory, headed to the Go'Shek Farm in the Arathi Highlands, and haven't checked in for days. Find them for me? I grow concerned.", objectives = "Find Quae and Kinelory near the Go'Shek Farm in the Arathi Highlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[660] = { title = "Hints of a New Plague?", description = "All right, $N. I'm ready if you are.\n\nShall we?", objectives = "Protect Kinelory until she returns to Quae.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[661] = { title = "Hints of a New Plague?", description = "I've seen Kinelory look way worse after a night in the tavern than she does now. You obviously did a good job protecting her.\n\nThese items she brought back from the farm should at least let Phin get an idea of what's going on out here in Arathi. Just to make sure there's no retaliation after your attack, we're going to stay here for a bit longer. Would you be willing to head back to Southshore and talk to Phin?", objectives = "Find Phin Odelic in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[662] = { title = "Deep Sea Salvage", description = "O'Breen led the ships into the cove.  We were certain this is where the treasure could be found.  The Harbinger docked safely but as the Maiden's Folly and Spirit of Silverpine approached the tides began to lower.  Strangest thing I've ever seen!\n\nThose two ships ran aground into something... some sort of temple in the reef.  They sank so quickly, was quite a tragedy.\n\nWe need to retrieve their Logs as well as their Charts before we leave.  We can't leave that information behind for prying eyes!", objectives = "First Mate Nilzlix wants you to retrieve the Charts and Logs from the Maiden's Folly and the Spirit of Silverpine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[663] = { title = "Land Ho!", description = "Lolo sees a tiny $r! Always on the lookout, Lolo is!\n\nWelcome to Faldir's Cove.  Captain O'Breen said we'd only be here for a few hours.  Just long enough to gather the treasure and get back to Booty Bay.\n\nBut Lolo thinks we're going to be here a lot longer than that.  We lost the other two ships from our formation.  Poor Spirit of Silverpine and Maiden's Folly.  On the bottom of the sea they rest now!\n\nLolo suggests you talk to Captain O'Breen if you plan on sticking around here.", objectives = "Talk to Captain O'Breen in Faldir's Cove.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[664] = { title = "Drowned Sorrows", description = "Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air.\n\nThe crew tried so hard to save my beautiful Maiden's Folly. Bless the boys, bless their hearts.\n\nO'Breen made it to shore safely but we weren't so lucky. The seas just sank on us, I swear.\n\nOne second we're afloat and the next water is rushin' in. And those beasts! Killed all the survivors. Horrible naga scum. I went black and ended up here, saved.\n\nI want those beasts dead.", objectives = "Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[665] = { title = "Sunken Treasure", description = "Now that we are full-fledged Blackwater Raiders it is our job to help Mr. O'Breen locate the lost elven treasure.\n\nIt is next to impossible to find the gems in the dark sea without aid. The doctor has constructed some goggles that will help. He needs the goggles charged with the energy derived from the enchanted stone in the cave just up the hill.\n\nBut the cave is cursed! When we get close, we get ambushed. Defend me and I can harness the energy from the stone into the goggles.", objectives = "Escort Professor Phizzlethorpe to the cave and back.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[666] = { title = "Sunken Treasure", description = "The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily.\n\nA little gnomish ingenuity goes a long way!\n\nSo borrow the Goggles of Gem Hunting, $n, and see if you can collect some of the lost treasure for Captain O'Breen.\n\nI'd swim down there myself but...um...well, I have important scientific business to tend to up on the safe, dry land....er, yeah.", objectives = "Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[667] = { title = "Death From Below", description = "This is bad. It seems the Daggerspines are amassing for an attack.\n\nNaga are known for their ruthlessness in battle. They will keep attacking until I am dead.\n\nI don't value my own life above that of my crew members, but you must help to defend me. The crew will not be able to make it back to Booty Bay without my knowledge of the seas.\n\nThe naga will be coming from the sea. I need you to remain up here with me to fend off the attack. Man the cannon and drive them back.\n\nAre you ready, $n?", objectives = "Protect Shakes O'Breen during the attack.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[668] = { title = "Sunken Treasure", description = "Let's not leave Captain O'Breen waiting. He'll want to see these gems first hand. After all, that's why we're here!\n\nAnd after a few weeks of consorting with these pirates, the professor and I have realized the last thing that's good for our health is to be caught hanging on to their treasure.\n\nHere, $n, take these to O'Breen.", objectives = "Take the Elven Gems to Captain O'Breen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[669] = { title = "Sunken Treasure", description = "Fleet Master Seahorn will want to hear about our find at once.\n\nBut as you can see, we're not in much of a position to get out of here. Not only is the tide too low, but those damned creatures we disrupted are keeping a close eye on our movements.\n\nYou can be of great service to the Blackwater Raiders if you can get word to Fleet Master Seahorn in Booty Bay that we discovered the treasure and are working on extracting more.  Take him this sample as proof.", objectives = "Take the Sample Elven Gem to Fleet Master Seahorn in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[670] = { title = "Sunken Treasure", description = "Say, $n, you seem to be an adventurous type. My fleet is stuck in Booty Bay until we can restock.\n\nThere are some heavy things brewing here and abroad and I need to get some top secret correspondence to Shakes O'Breen who is tied up off the Arathi coast.\n\nCan I trust you to deliver this message safely and in confidence?", objectives = "Deliver Seahorn's Letter to Shakes O'Breen in Arathi Highlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[671] = { title = "Foul Magics", description = "I have felt a strangeness in the air... a feeling that simmers in my blood. I had my suspicions. I set off to find the source of my unease and discovered to the west, at Northfold Manor, the residual traces of demonic summoning. As I got close, my blood began to boil and the rage within me grew.\n\nOn the ground I spied an amulet of bloodstone, used to assist in demonic summoning. The one I found was depleted, however. I'll need another to examine, but I dare not return to the manor. Can you bring me some?", objectives = "Get 10 Bloodstone Amulets for Tor'gan in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[672] = { title = "Raising Spirits", description = "We tried to settle him in, cheer him up, telling him stories of our mighty city at Orgrimmar in Kalimdor, but nothing would move him.\n\nTales of our young Warchief, Thrall, who bears the armor and hammer of Orgrim... but, perhaps... Perhaps! A demonstration of our newly found shamanistic magic would give him new hope. It is worth a try!\n\nA small object we could make for him, yes... Bring me some raptor eyes, and I will see what I can do.", objectives = "Acquire 10 Highland Raptor Eyes from Highland Striders and Highland Thrashers for Tor'gan in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[673] = { title = "Foul Magics", description = "There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers. We must remove the source of his energy.\n\nFind the warlock and kill him. Bring me whatever magical object you find on his person, and I will take steps to destroy it and see that its power is not used to taint this land any longer.", objectives = "Retrieve Marez Cowl's Bloodstone Orb and bring it to Tor'gan in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[674] = { title = "Raising Spirits", description = "Here, take this amulet to Gor'mul, and see if the raptors' strength can awaken the flame of the warrior that once burned through his veins.", objectives = "Give the Raptor Talon Amulet to Gor'mul.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[675] = { title = "Raising Spirits", description = "<Gor'mul tosses the amulet into the ground.>\n\nTor'gan sent you, didn't he? Pah! Why he feels some mercy towards me I would not understand. Mercy was denied me when I was not allowed to die with my Warchief in battle. A cruel blow fate has dealt me...", objectives = "Speak with Tor'gan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[676] = { title = "The Hammer May Fall", description = "Weaklings... all of them. You, $c, what are you looking at? Think you're something special, huh? Why not prove it?\n\nThe Hammerfall outpost in Arathi's under attack. Unless we send them help soon, their demise is imminent.\n\nBut before you go rushing off, you may want to test your skills first. Northeast of Stromgarde in Arathi is an ogre mound inhabited by the Boulderfist tribe. When you can handle the ogres and enforcers there, then report to Drum Fel in Hammerfall.", objectives = "Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers, then find Drum Fel in the Hammerfall outpost in Arathi Highlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[677] = { title = "Call to Arms", description = "The Witherbark trolls and Boulderfist ogres of Arathi are working together to rid us from this land, but we shall not meet our fates at their, or anyone else's, hand. We will slay them and show them that we, too, have a home here. \n\nThe trolls turned their backs to us; the ogres would use us for food and bedding if we allowed them to--these things shall not be.\n\nWe start our attack on the Witherbark trolls to the south of here. Slay them in droves, and only return when their camps run thick with blood.", objectives = "Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors, and return to Drum Fel in the Hammerfall outpost.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[678] = { title = "Call to Arms", description = "Your strength is evident, $N. Now to see how you fare against a real enemy.\n\nThe Boulderfists have a lair to the southwest of here towards the dwarven bridge, and, if I'm not mistaken, the maulers and magi there shall present to you a greater challenge--they have done so to us thus far.\n\nSlay as many as you can and come to me in body when you are successful, or come to me in spirit when you fail. I shall give praise to your tenacity in battle either way.", objectives = "Kill 10 Boulderfist Brutes and 4 Boulderfist Magi, and return to Drum Fel in the Hammerfall outpost.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[679] = { title = "Call to Arms", description = "The head of the beast is ready to be taken off... with great force, $N. You have shown every sign that you are able to help us with this final mighty blow. The leaders of these attacks have made their lair within the ruins of Stromgarde, a glaring symbol of human frailty.\n\nFind and slay those Boulderfist lords and their lackey shaman who would try and drive us from these lands.", objectives = "Kill 15 Boulderfist Shaman and 10 Boulderfist Lords and return to Drum Fel in the Hammerfall outpost.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[680] = { title = "The Real Threat", description = "You serve my husband well, $c, but he does not know why Hammerfall is under attack.\n\nOr'Kalar, Mug'thol's pawn in Stromgarde, has an intense hatred for my husband, and wishes nothing more than my husband's death for defeating him years ago.\n\nMy auguries tell me that Or'Kalar has laid a trap for my husband, so I have hidden signs of the ogre's presence from him.\n\nMy husband will rush off foolishly if he learns of the ogre's whereabouts and I would ask for your help in slaying the creature.", objectives = "Slay Or'Kalar and bring his Head to Korin Fel in the Hammerfall outpost.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[681] = { title = "Northfold Manor", description = "We are fighting a war for Stromgarde, and we are losing.  The ogres, the Syndicate and we have divided our once great city, and each faction battles the other into a bloody stalemate.\n\nBut our forces dwindle while our enemy grows.\n\nWe need help from the town of Southshore, but supplies are difficult to receive while the Syndicate holds territory between us.\n\nGo to the Syndicate base in Northfold Manor and slay them.  Then, perhaps, pressure on our supply trains will lessen and more will get through.", objectives = "Kill 10 Syndicate Highwaymen and 6 Syndicate Mercenaries.\n\nReturn to Captain Nials at Refuge Pointe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[682] = { title = "Stromgarde Badges", description = "The Syndicate in Stromgarde do battle with our contingent of militia there. In order to urge the rabble to fight our more disciplined troops, the Syndicate leaders have placed a bounty on our soldiers, awarding gold for each Stromgarde Badge gathered off killed militiamen.\n\nWe want those badges retrieved - we cannot allow the cutthroats to take trophies from our brave fallen!\n\nEnter the Syndicate-controlled area of Stromgarde and hunt them for our badges.", objectives = "Bring Stromgarde Badges to Captain Nials at Refuge Pointe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[683] = { title = "Sara Balloo's Plea", description = "$n, I have but a small request to ask of you.\n\nTake this note I have prepared to our great monarch of Ironforge, King Magni Bronzebeard. 'Tis a small task to ask of one such as yourself, someone who has shown great valor to the cause of the Alliance thus far.\n\nFor me to go before the King in my grief-ridden state would not serve the purpose of my cause.  Surely you understand.", objectives = "Take Sara Balloo's note to King Magni Bronzebeard of Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[684] = { title = "Wanted!  Marez Cowl", description = "A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate.  She was last seen within the Syndicate controlled territory of Stromgarde.\n\nBounty may be collected from Captain Nials.\n\nBe warned: Marez is a skilled and cunning Warlock, known for her trafficking with demons.  Extreme caution is advised when hunting her.", objectives = "Bring Marez's head to Captain Nials at Refuge Pointe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[685] = { title = "Wanted!  Otto and Falconcrest", description = "The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto.  Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts.\n\nHis bodyguard Otto, although not a strategic target, is a fierce opponent and has killed dozens of our defenders.\n\nTheir bounties may be collected from Captain Nials.", objectives = "Bring Otto's Head and Falconcrest's Head to Captain Nials at Refuge Pointe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[686] = { title = "A King's Tribute", description = "I do not expect good dwarves like Mrs. Balloo to understand why the travesties of war must be endured for the greater good of our people. The loss of her husband, and the loss of every dwarf that fights in the name of the Alliance, weighs heavy on my soul.\n\nWhile I cannot bring her husband back from the Twisting Nether, I can pay tribute to him.\n\nI am going to commission a memorial to Sully Balloo to be built by Grand Mason Mablesten.\n\nSend word to him now, $c. You shall be custodian of my bidding.", objectives = "King Magni Bronzebeard wants you to speak with Grand Mason Marblesten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[687] = { title = "Theldurin the Lost", description = "Theldurin the Lost was once a member of our order, the Twilight's Hammer.  But he lost his mind and scorned our teachings.  And before he fled from us, he stole the scroll of Myzrael!  We could not catch him, but rumors say he hides in the Badlands, gibbering and mad.\n\nTo bring the Lady back to us, you must find the scroll.  And to do that, you must find Theldurin.", objectives = "Find Theldurin the Lost.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[688] = { title = "Myzrael's Allies", description = "<Myzrael speaks.>\n\nFree!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me.\n\nBut in time I will confront the giants, and they will regret their wardship of me!\n\nYou are a noble ally, $N.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface\n\nSpeak with Zaruk in Hammerfall.  He knows how I can be summoned.", objectives = "Speak with Zaruk in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[689] = { title = "A King's Tribute", description = "So our good King would like a memorial built in honor of a soldier named Sully Balloo?  And you say the poor chap died during the Thandol Span tragedy?\n\nBah, will there ever be peace on Azeroth?\n\nNonetheless, any commission from the King is of utmost importance. To build a truly epic and lasting piece I want to work with one of the finest stones available. Travel to Darrow Hill in Hillsbrad and gather for me some Alterac Granite.", objectives = "Grand Mason Marblesten of Ironforge wants 5 pieces of Alterac Granite.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[690] = { title = "Malin's Request", description = "Greetings, $N. You have the look of an adventurer about you, and I have a task that needs some tending to.\n\nArchmage Trelane, my original master, fled Stromgarde in the Arathi Highlands not too long ago, and he's asked me to help him in recovering some of the items he left behind.\n\nThe city fell under siege, and he attempted to defend the Tower of Arathor, but to no avail. I have agents in the Highlands already, but they've requested I send more aid. Are you interested?", objectives = "Find Skuerto at Refuge Pointe in the Arathi Highlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[691] = { title = "Worth Its Weight in Gold", description = "Archmage Malin sent Skuerto and I here to collect reagents for him. I was at a loss as to how I was going to collect the items, but now that you're here, I think my problem's solved.\n\nI need the following: Witherbark tusks, Witherbark medicine pouches and a shadow hunter knife.\n\nCould you find those for me? The Witherbark live to the southeast of Arathi.", objectives = "Find 10 Witherbark Tusks, 4 Witherbark Medicine Pouches and a Shadow Hunter Knife for Apprentice Kryten at Refuge Pointe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[692] = { title = "The Lost Fragments", description = "The Scroll of Myzrael...the Scroll of Myzrael?!  You don't want that!  Its magic can pull Myzrael to the surface world and if you do that, we are in trouble!\n\nOr...maybe it's too late.  Maybe she already is free.  Maybe she's just gathering strength before unleashing herself upon us.  If so, then you'll NEED the scroll!\n\n...too bad it's destroyed.  Enraged elementals stole it and tore it up and now fight over the fragments.\n\nBut if you can gather those fragments, maybe we can fix it...", objectives = "Bring the Torn Scroll Fragment, the Crumpled Scroll Fragment and the Singed Scroll Fragment to Theldurin the Lost.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[693] = { title = "Wand over Fist", description = "Hey, $N. Sorry to be so short with ye earlier... and no, that ain't a pun.\n\nI figured out where Trelane's first item ended up: Kor'gresh has it in Boulderfist Hall. An' by the way he was throwing down blasts of ice at his kin to keep them in line, he must be close to figurin' out how to use all of its powers.\n\nBoulderfist Hall's south of here an' then east of Thandol Span. Find the ogre an' get back that wand.\n\nWhile you're gone, I'll figure out what we're gonna do about Stromgarde.", objectives = "Find Trelane's Wand of Invocation and return it to Skuerto at Refuge Pointe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[694] = { title = "Trelane's Defenses", description = "All rested?\n\nHere's our next step: there're ogres all around the Tower of Arathor in Stromgarde. We're gonna need to activate the tower's defenses if you're gonna stand a chance against 'em an' still make it to the items alive. To do that, we're gonna need some gems the Boulderfist shaman have taken a liking to. They took 'em from the tower, but they're not gonna stay in their possession for long.\n\nGet one of them gems an' bring 'em to Kryten--he knows the spell to enchant 'em so they'll work as a key.", objectives = "Find an Azure Agate and bring it to Apprentice Kryten at Refuge Pointe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[695] = { title = "An Apprentice's Enchantment", description = "Here you are, $N. The gem only needs to be pressed against one of the pedestals near the base of the tower to activate its defenses. Use it when you're ready to enter the tower and find Trelane's remaining items. \n\nGood luck to you. I'll be awaiting your return here at the camp. Oh, and speak to Skuerto before you leave. He'll give you the rest of the details you'll need.", objectives = "Speak to Skuerto.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[696] = { title = "Attack on the Tower", description = "Here's what your lookin' for: Trelane's phylactery, Trelane's orb, an' Trelane's ember agate.\n\nAll three should be in chests within the tower an' you shouldn't have a problem opening the chests on your own; you just have to be careful of the ogres.\n\nThe tower's defenses won't take care of 'em on their own; you'll need to have your weapons at the ready. Those ogres find out you're there and stealing from 'em, an' they'll be sure to put the hurt on you.\n\nBe careful, an' good luck.", objectives = "Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[697] = { title = "Malin's Request", description = "Take this letter back to Stormwind and let Malin know that Kryten an' I'll be home soon. He'll reward you well for helping us here, $N, of that I've no doubt.\n\nTravel safely.", objectives = "Take the Sealed Letter to Archmage Malin in the Mage Quarter of Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[698] = { title = "Lack of Surplus", description = "I'm working on getting some supplies together for our outpost near the beach to the east--Tok'kar does what he can, but between shifts of guard duty and cooking for his soldiers there's not much time left in the day.\n\nThey do enjoy cooking up some sawtooth meat when they can, but I haven't had time to get them another shipment. Would you mind helping them out?\n\nThe young sawtooths aren't as tasty as the older ones, so stay clear of those; give them a year or two to get to full size.", objectives = "Bring 8 Unprepared Sawtooth Flanks to Tok'Kar in Swamp of Sorrows.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[699] = { title = "Lack of Surplus", description = "With the threat of murlocs along the coast, we're stationed out here to protect--or warn if the force is too large--of any coming threats to Stonard. It doesn't give us much time for relaxation, and we could use some more help if you're able.\n\nThe sawtooth snappers' claws make for fine weapons when properly prepared. Bring me some of their claws and I'll see you're rewarded with one of our weapons in thanks for the fresh meat and the good company.", objectives = "Bring 6 Sawtooth Snapper Claws to Tok'Kar in the Swamp of Sorrows.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[700] = { title = "A King's Tribute", description = "Ah, such fine stone comes from Lordaeron.  Such a shame the land is in such shambles.\n\nBut the Memorial came out quite well! I should think the King will be most pleased with it.\n\nNow if you will, please send word to His Majesty that the Memorial is complete as requested. ", objectives = "Report to King Magni Bronzebeard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[701] = { title = "Guile of the Raptor", description = "With some additional objects, I will be able to create an item that will imbue Gor'mul with the guile of the raptor! With the power of the raptor flowing through him, Gor'mul will know our new power and rediscover the warrior that lies dormant!\n\nI will require raptor hearts to fashion the item and spell.", objectives = "Acquire 12 Raptor Hearts from Highland Fleshstalkers for Tor'gan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[702] = { title = "Guile of the Raptor", description = "Take this orb and use its energy to give Gor'mul the essence of the raptor. Surely this will invigorate his spirit and give him new purpose in life. With him returned to normal, we can explain to him the current state of the Horde, and we will have a great warrior's assistance in our unceasing battles.", objectives = "Give Tor'gan's Orb to Gor'mul.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[703] = { title = "Barbecued Buzzard Wings", description = "Oh yes, my barbecued buzzard wings are a favorite!  The sauce is rich and the meat is tangy.  And the smell will bring the hungry running from miles away!\n\nI have everything I need to cook up a batch.  Everything...except the buzzard wings!\n\nIf you want some then get me the buzzard wings.  Bring me enough, and I might even share the recipe with you!", objectives = "Bring 4 Buzzard Wings to Rigglefuzz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[704] = { title = "Agmond's Fate", description = "The last report I received from Agmond is troubling, more so now that he's dead!  He mentioned that his diggers uncovered \"ancient urns\" at the dig site outside Uldaman.  I fear that the urns he found at that site incited the troggs, just as did the idols I found here.\n\nI need you to get those urns for our studies.  Go to the Uldaman site, gather the urns, then return to me.", objectives = "Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[705] = { title = "Pearl Diving", description = "The Badlands is a harsh place, filled with vicious predators and bold scavengers.  Scary, especially for a short little goblin.  To survive, I have to be tricky!\n\nI know the recipe for flash bombs.  I use those to scare away wildlife.  But I'm running low on one of the ingredients: crushed blue pearl powder.  Get me some and I'll make it worth your efforts.\n\nHeh, and I hope you have good boots on.  The Blue Pearls I need are found from clams at the Vile Reef.\n\nYep, the Vile Reef in Stranglethorn!", objectives = "Bring 9 Blue Pearls to Rigglefuzz in the Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[706] = { title = "Fiery Blaze Enchantments", description = "As an apprentice to Feranor Steeltoe, I learned his special technique for imbuing weapons with fiery enchantments. Last I heard of him, he was working at a smithy with a hunting party up in Lordaeron.\n\nI can't tell you too many of the details about the process, but I can tell you it requires blood from a rare, still-beating black drake whelp's heart. I don't have much to do waiting for word from Ironforge. If you bring me a heart from the whelps in Lethlor Ravine, I'll show you my skill!", objectives = "Acquire a Black Drake's Heart for Sigrun Ironhew.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[707] = { title = "Ironband Wants You!", description = "$N.  I received reports from Prospector Ironband at his excavation site in Loch Modan--he needs some legwork done concerning another of our excavations.\n\nI don't have more details than that, but if you want to stretch your legs then go speak with Ironband.", objectives = "Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[708] = { title = "The Black Box", description = "The surface of this metallic black box is heavily pitted, as if it had been immersed in acid - it must have been sitting in the giant condor's stomach for a long time.\n\nTurning the box over, a symbol is found stamped on its bottom.  Below the symbol are the words:\n\n\"Engine #19 - Ironforge Siege Brigade\"", objectives = "Take the Corroded Black Box to the Hall of Arms in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[709] = { title = "Solution to Doom", description = "Oh my!  Oh my!  There is a doom approaching.  Mark me!  A doom!\n\nNo, I cannot speak of it...cannot utter their names or they may hear me!  But if we learn, yes, if we learn more of them...then maybe we can learn how to foil them!\n\nMaybe.\n\nGo into Uldaman.  No!  I said it!  You must find...find the tablet of...Ryun'eh.  Yes, find it!  And don't make me speak that name again!\n\nIt is deep in that place, in an ancient chest.  That's where it hides...in a chest crafted before the works of any dwarf.", objectives = "Bring the Tablet of Ryun'eh to Theldurin the Lost.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[710] = { title = "Study of the Elements: Rock", description = "Here in the Badlands I've stopped to work on my latest project: my shackles of elemental binding.\n\nWhen complete, they will allow mages to summon even more powerful elementals for use in even greater capacities. To start things off, I need small stone shards to test some of my newest offensive spells along with a few gizmos I've pieced together.\n\nThe shards are easily collected from the lesser rock elementals to the west of here. Could you bring me some?", objectives = "Find 10 Small Stone Shards and bring them to Lotwil Veriatus in the Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[711] = { title = "Study of the Elements: Rock", description = "$N, you've already proven more able than all my apprentices combined.\n\nThe next parts I need require a little more strength. Large stone slabs can be found on rock elementals if you're careful enough. Their bodies are stronger and larger, and therefore more prone to having pieces large enough for my tests. You can find them further west of here or southeast along the mountains' edges.\n\nTake your time; I'll need a while to test these smaller pieces you brought me.", objectives = "Bring 3 Large Stone Slabs to Lotwil Veriatus in the Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[712] = { title = "Study of the Elements: Rock", description = "$N, there's one more part I need from the elementals here in the Badlands: the bracers of rock binding from the greater rock elementals. By my calculations, those bracers should be enough to gauge the strength of my own shackles.\n\nMy attempts at scrying the greater rock elementals showed a group of them southwest of here, near some ogres if I recall.\n\nBring me 5 of their bracers just so I have extras. Servo's notorious for misplacing my reagents and research.", objectives = "Bring 5 Bracers of Rock Binding to Lotwil Veriatus in the Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[713] = { title = "Coolant Heads Prevail", description = "Let me tell you something about Frost Oil: nothing can keep an engine or gears from overheating quite like it.\n\nIts cooling properties are extraordinary, and its longevity as a lubricant without equal. That's not all: it also aids in retaining enchantments on magical items.\n\nI need a vial of it to increase the magical capacity of my shackles and make them powerful enough to stop our summoned friend from killing us all.\n\nBro'kin, a goblin friend of mine, can teach you to make it. He's in Alterac.", objectives = "Find Frost Oil and bring it to Lotwil Veriatus in Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[714] = { title = "Gyro... What?", description = "$N, you've done your job well beyond all standards.\n\n<Lotwil's obviously distracted by his work.>\n\nIf we ever meet in Kharanos, feel free to come apply for work.\n\nWhoops! Quick, grab the... yes, that. Thanks.\n\nNow I just need one more thing. It's a small part, but rather crucial, I'm afraid: a gyrochronatom.\n\nIf you could just go grab one and bring it to me, I should be ready to complete this.", objectives = "Bring a Gyrochronatom to Lotwil Veriatus in the Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[715] = { title = "Liquid Stone", description = "I'm thinking those items you acquired for Lotwil are going to be the least of our worries, $N. On the other hand, you've proven more than adept at the sciences Lotwil holds sacred, so how about helping me out?\n\nI need an invisibility potion and a healing potion; both might come in handy real soon if he pulls this off.\n\nIn return, I'll give you this recipe for a potion I've been developing while learning from Lotwil. It's based on some of the research he's been doing here in the Badlands.", objectives = "Bring a Healing Potion and a Lesser Invisibility Potion to Lucien Tosselwrench in the Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[716] = { title = "Stone Is Better than Cloth", description = "I know how cheap Lotwil can be, $N, so let me make you something for all your troubles. Maybe it'll even help protect you from the coming atrocity that is Lotwil's newest invention.\n\nI've been working with all the extra stones you collected for him, and I can make some nice bracers that you might want to use. They're enchanted, of course.\n\nI'll just need patterned bronze bracers crafted by a blacksmith so I can complete the bracers I'm making for you.", objectives = "Bring some Patterned Bronze Bracers to Lucien Tosselwrench in the Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[717] = { title = "Tremors of the Earth", description = "It has become obvious that we cannot ensure that Blacklash and Hematus will remain imprisoned in Lethlor. That black dragons have taken up residence there, and that the ogres managed to steal the Sign indicates that more drastic measures will have to be taken.\n\nThe drakes' prison is maintained by three runestones that may only be retrieved using the Sign of the Earth. Those runestones can then be used to break the seal which imprisons them.\n\n$n... assure that their dreams are eternal.", objectives = "Use the Sign of the Earth to activate the Pillars of Amethyst, Opal, and Diamond and obtain the Runestones.\n\nPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.\n\nSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Garek.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[718] = { title = "Mirages", description = "In our hurry to leave the Uldaman excavation site, we were forced to abandon many wagons and crates of supplies along the way. The local ogres from Camp Kosh have been on our abandoned equipment like vultures on a rotting corpse. Don't smell much better, either. Than the corpses, I mean.\n\nAnyways, they took the cart that was carrying all our weapons and such... so--well, this is a bit embarrassing--we haven't been able to get any food.\n\nWe're in a bit of a pickle here, suppose you could help us out?", objectives = "Retrieve the Supply Crate for Sigrun Ironhew.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[719] = { title = "A Dwarf and His Tools", description = "Hey, $N. Be careful 'round here. There be Dark Iron dwarves all around--looked like the Shadowforge clan.\n\nThey just attacked the excavation site I was workin' at--killed nearly everyone there, including my boss Hammertoe. I barely escaped with me life.\n\nThe site's just to the north of here, and I'm tryin' to plan a way to get some of our supplies back, especially me lucky pick.\n\nThink you'd be up to helpin' me out some? One of those damned Dark Iron must have my pick! Could be anyone of them.", objectives = "Find Ryedol's Lucky Pick and return it to Prospector Ryedol south of Hammertoe's Dig Site.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[720] = { title = "A Sign of Hope", description = "<There is text roughly scribbled in chalk on the map.>\n\n\"Ryedol, \nThey're taking me to Uldaman. Send help.\n-Hammertoe\"", objectives = "Find Prospector Ryedol and let him know Hammertoe Grez is alive.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[721] = { title = "A Sign of Hope", description = "$N, can ye find him? Can you find Hammertoe in Uldaman?\n\nIf those dirty Shadowforge are holdin' him hostage to figure out what he knows about the titan excavations, then all of Ironforge could be in huge trouble.\n\nFor a long time now those Dark Irons have been lookin' for magics to make more powerful golems. Hammertoe was doin' the same, of course, but only to stop them.\n\nThey're probably keepin' him alive until they learn what he knows.Ye've got to hurry if you're gonna save him!", objectives = "Find Hammertoe Grez in Uldaman.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[722] = { title = "Amulet of Secrets", description = "Ye're brave... <cough>... to come into Uldaman fer me, $c.\n\nIf ye're really here to help... ol' Hammertoe, then... <cough>... you'll need to find... me amulet.\n\nDeepshadow's got it... Magregan Deepshadow. He's 'round here... in the ruins fer sure. That amulet'll lead 'em... <cough>...  right to the scrolls if he ain't stopped. It's up to you, $N. Please... get that amulet.\n\nThe scrolls will surely help the Dark Irons create even more powerful golems. I just know it. I can feel it in me bones.", objectives = "Find Hammertoe's Amulet and return it to him in Uldaman.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[723] = { title = "Prospect of Faith", description = "<Hammertoe holds his wounds and takes a moment to regain his composure before speaking again.>\n\nFind Ryedol, $N. Bring 'im me amulet. <cough cough> He'll... <cough> figure out what to do. He knows I was seeking the origins of our people, and he... <cough>... knows it was also my mission to stop the Shadowforge clan. They must not be allowed to find the scrolls... <cough>", objectives = "Take Hammertoe's Amulet to Prospector Ryedol in the Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[724] = { title = "Prospect of Faith", description = "Okay, okay... who would know what to do?\n\nHistorian Karnik! That's it!\n\nHe's in Ironforge. He'll be able to help. He and Hammertoe were workin' together to find the lost artifacts in Uldaman.\n\nGuess the Shadowforge found out the two of them knew more than they were lettin' on.\n\nTell Karnik what's happened to Hammertoe and give him the amulet--he'll tell you what needs to be done next.", objectives = "Take Hammertoe's Amulet to Historian Karnik in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[725] = { title = "Passing Word of a Threat", description = "$N, run and find Advisor Belgrum as quickly as you can. Tell him what you've witnessed and ask him how he wants us to proceed. This note will explain more to him.\n\nIn the meantime, I will take the time to speak to Hammertoe's spirit. Maybe he knows something that will help us put a stop to those Shadowforge cretins' activities in the Badlands. We can only pray.", objectives = "Find Advisor Belgrum and give him his note.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[726] = { title = "Passing Word of a Threat", description = "<Advisor Belgrum reaches the end of the note, and his eyes widen for a moment.>\n\nOch, these are evil tidings.\n\n$N, please return to Historian Karnik and tell him on the king's authority to act on this information swiftly and decisively. He must halt the Shadowforge's activities in the Badlands.", objectives = "Speak to Historian Karnik.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[727] = { title = "To Ironforge for Yagyin's Digest", description = "The Tablet tells much.  But not enough!  Not nearly enough!\n\nThere is a book, a digest that Yagyin wrote in ages past.  The ... people I fled ... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us!\n\nGo to Gerrig Bonegrip.  He is in a shop in Ironforge, in the Forlorn Cavern.  Show him this sigil and he'll think you one of them.  Ask him for Yagyin's Digest ... and bring it to me!", objectives = "Give the Sigil of the Hammer to Gerrig Bonegrip in the Forlorn Cavern of Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[728] = { title = "To the Undercity for Yagyin's Digest", description = "The tablet tells much.  But not enough!  Not nearly enough!\n\nThere is a book, a digest that Yagyin wrote in ages past.  The... people I fled from... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us!\n\nGo to Keeper Bel'dugur in the Undercity of Lordaeron.  Show him this sigil and he'll think you one of them.  Ask him for Yagin's Digest...and bring it to me!", objectives = "Bring the Sigil of the Hammer to Keeper Bel'dugur in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[729] = { title = "The Absent Minded Prospector", description = "What an honor it was when Master Greywhisker assigned me to work under the guidance of the great Prospector Remtravel. At the academy in Ironforge everyone knew of Remtravel's great discoveries.\n\nBut the prospector is rather... um... oblivious ...to his surroundings.\n\nWe had uncovered evidence of a great society. Horrible golems sprang forth from the ground and overran the site. Remtravel never seemed to notice. I ran back to Auberdine for help.\n\nPlease travel south and see if the prospector is ok!", objectives = "Travel south and check on Prospector Remtravel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[730] = { title = "Trouble In Darkshore?", description = "How nice it is to see a $c interested in the great archeological wonders of our world.\n\nOftentimes our work is dismissed as mere hobby by our friends in the Alliance. But what many fail to realize is that recent discoveries in Khaz Modan have proven that a great and powerful force threatens all of Azeroth, from Lordaeron to Kalimdor.\n\nI am most worried about my crew that I sent to Darkshore. They haven't sent word in weeks.\n\nTravel to Auberdine and look for a clue as to their whereabouts.", objectives = "Travel to Auberdine and look for signs of the dwarven excavation team.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[731] = { title = "The Absent Minded Prospector", description = "So then, Hollee... oh that's right, you are not Hollee. Where's Hollee?\n\nBah, that's beside the point. We must find that stone brush... I mean the mysterious fossil! We must find that fossil. The Explorers' League in Darnassus will want some indication as to what I've been doing.\n\nLet me know when you are ready and we will hunt down that brush.... I mean fossil! We shall find something in writing to satisfy the League.\n\nSo are you ready yet?", objectives = "Protect Prospector Remtravel as he searches for the mysterious fossil, then return to Archaeologist Hollee in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[732] = { title = "Tremors of the Earth", description = "I heard from Sigrun that you have been a great help to him. Perhaps I might enlist your help. I was sent here by my master, Krasus of the Kirin Tor, to put an end to the trouble brewing in Lethlor Ravine.\n\nI cannot divulge the exact nature of my assignment here or the tasks that I must undertake, but be assured it is of vital importance.\n\nA band of wandering ogres, sometimes seen near Camp Boff, stole an object called the Sign of the Earth; I must have it. Bring it to me, and I will tell you more.", objectives = "Retrieve the Sign of the Earth for Garek.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[733] = { title = "Scrounging", description = "It's going to be tough going here if I can't manage to scrounge up some materials to construct some defenses and other necessities. I've noticed that the ogres in the area seem to be well equipped with scrap metal. Maybe the stories of siege engines in the Badlands weren't so far off after all...\n\nAnyways, the Prospector's been getting worried about the state of our little camp, so I'd like to get working soon if I can.\n\nThe main ogre camp is at Dustbelch Grotto, a good trek to the west of here.", objectives = "Get 7 pieces of Scrap Metal for Sigrun.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[734] = { title = "This Is Going to Be Hard", description = "Wonderful, wonderful.\n\n<Lotwil looks up at you for a moment before going back to his shackles.>\n\nGo speak to Lucien, $N. I need a cog #5. Bring it to me, will you?", objectives = "Speak to Lucien Tosselwrench in the Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[735] = { title = "The Star, the Hand and the Heart", description = "Yagyin's Digest, eh?  Are you starting a new chapter of us, somewhere?  Never mind, it is not my place to ask.\n\nI will help you, for I have an extra copy.  We must aid each other, yes?  That is how we flourish.\n\nI require three items of power.  Bring them to me and I will give you the digest.\n\nI will not speak their names.  Ears may be on us.  But here, I will write them down.", objectives = "Return the items on the Bonegrip's Note to Gerrig Bonegrip in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[736] = { title = "The Star, the Hand and the Heart", description = "You need Yagyin's Digest?  Your plan, then, is to gather another flock?  Of course it is...and of course I will help you, $gbrother:sister;.\n\nBut you must help me too.\n\nI require three items of power.  Bring me these and the digest will be yours.\n\nI cannot utter the names of these items, but I will write them down.\n\nGet me the items on this list.  If you can do that, then you are truly worthy of opening your own chapter of our order.", objectives = "Bring the items on Bel'dugur's Note to Keeper Bel'dugur in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[737] = { title = "Forbidden Knowledge", description = "I have the digest for you, $N.  I need not tell you to take great care with it.  And to keep it far from unfriendly hands.  \n\nThis book holds many truths...\n\n...And the truth can burn.", objectives = "Bring Yagyin's Digest to Theldurin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[738] = { title = "Find Agmond", description = "Prospector Agmond was in charge of our excavation sites in the Badlands, to the southwest.  I say \"was\" because...well, I haven't heard from him in weeks.  I need you to find Agmond so I can get his report.\n\nLast I heard Agmond was at the southernmost dig site in the Badlands--a tiny operation past the Angor Fortress.  I'd start your search for him there.", objectives = "Find Agmond.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[739] = { title = "Murdaloc", description = "Agmond's tracks lead from the west.  It is easy to tell from the bloody smears across rock and sand that the dwarf crawled some distance.\n\nAnd here he died.\n\nUpon close inspection, the word \"Murdaloc\" is roughly scrawled in a patch of Badlands sandstone.\n\nScrawled next to Agmond's dead hand.", objectives = "Slay Agmond's killer, Murdaloc.\n\nSlay 12 Stonevault Bonesnappers.\n\nReport to Prospector Ironband in Loch Modan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[741] = { title = "The Absent Minded Prospector", description = "So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus? I don't feel right leaving Darkshore without him.\n\nHere, $n, deliver the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.", objectives = "Take the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[742] = { title = "The Ashenvale Hunt", description = "Attention, young adventurers!  The wilds of Ashenvale await you!\n\nThe Horde has established a strong presence in the lands north of the Barrens.  Our two outposts - Splintertree Post and the Zoram Strand Outpost - strive to bring glory to the Horde!  Those who would prove themselves should seek out guidance there.  Of note: Senani Thunderheart in Splintertree Post, directly north of the Barrens, seeks adventurers willing to take part in a great hunt of Ashenvale!", objectives = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[743] = { title = "Dangers of the Windfury", description = "Thank you for taking the time to speak to me, $N. I am Ruul, warrior and teacher.\n\nYou have obviously reached an age when you must prepare for your trials if you are to adventure much further out of Mulgore.\n\nIf you wish a test of your strength, start by seeking out the Windfury harpies to the southeast. They nestle along the mountain's edges away from the road.\n\nThey are one of our natural enemies here in Mulgore and will be a good gauge of your skill.", objectives = "Bring 8 Windfury Talons to Ruul Eagletalon in Bloodhoof Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[744] = { title = "Preparation for Ceremony", description = "$N, my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him.\n\nI want to ask a favor of you while I finish tanning these leather straps. There is not time for me to find enough feathers, and I was wondering, would you gather more for me?\n\nYou can find feathers of the correct size from the harpies residing far to the north and northwest of Thunder Bluff. I need only 6 azure and 6 bronze feathers to complete the design.", objectives = "Collect 6 Azure Feathers and 6 Bronze Feathers, and bring them to Eyahn Eagletalon in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[745] = { title = "Sharing the Land", description = "$N, there are many conflicts that wound this land. It is my hope that you will not bear witness to as many of them as I have. Yet there is one that I would ask you to seek out. It will give you some sense of how terrible, if left unchecked, even a small threat can be to the land.\n\nPalemane gnolls have settled to the south of Bloodhoof and in a cave to the west. They disrespect our attempts to communicate with them, and they slay the wildlife of Mulgore unbridled.\n\nWords are no longer the answer.", objectives = "Kill 10 Palemane Tanners, 8 Palemane Skinners, and 5 Palemane Poachers, then return to Baine Bloodhoof in Bloodhoof Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[746] = { title = "Dwarven Digging", description = "There are dwarves preparing a dig site to the northwest.  They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings.\n\nCollect the dwarven tools of digging, smash them, and return to me with the dwarves' broken tools.\n\nYou can smash the tools at a forge.  You will find one in Thunder Bluff, but any forge -- even a forge at the dwarven camp -- will suffice.", objectives = "Collect 5 Prospector's Picks.\n\nAt a forge, smash the Prospector's Picks to create Broken Tools.\n\nBring 5 Broken Tools to Baine Bloodhoof in Bloodhoof Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[747] = { title = "The Hunt Begins", description = "You have a promising air about you, and will prove yourself to the tribe. Perhaps someday soon you will be welcomed into the great city of Thunder Bluff. But before that can happen you must prove yourself to my father, Chief Hawkwind.\n\nUp here on Red Cloud Mesa we pride ourselves on keen hunting skills. Tauren hunt out of necessity and for sport. Our supply of meats has run low and we require feathers for clothing. Hunt the nearby plainstriders and prove yourself by resupplying the village.", objectives = "Grull Hawkwind in Camp Narache wants you to bring him 7 Plainstrider Feathers and 7 pieces of Plainstrider Meat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[748] = { title = "Poison Water", description = "Goblins and their servants have tainted our sacred water wells!  We cannot allow this.\n\nTo cleanse each well, I must create a cleansing totem, then you must bring the totem to the well and perform a cleansing ritual.\n\nFirst we will create a cleansing totem for the Winterhoof Water Well.  To do this, the land must offer its aid. Hunt prairie wolves for their paws and adult plainstriders for their talons.  They are to the southwest.\n\nReturn to me with the paws and talons, $N.", objectives = "Bring 6 Prairie Wolf Paws and 4 Plainstrider Talons to Mull Thunderhorn in Bloodhoof.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[749] = { title = "The Ravaged Caravan", description = "A few days ago, we found a Venture Co. caravan traveling under guard on the northern shore of Stonebull Lake. We'd lost two of our number in an earlier battle, so we were quick to attack and lay waste to the caravan.\n\nWe left their supply crates, thinking that our torches would destroy anything of value, but given that Venture Co. salvagers have been spotted near the burned wagons, maybe we were wrong.\n\nPerhaps you could go to the caravan and examine the contents of the crates.", objectives = "Morin Cloudstalker wants you to examine the contents of a supply crate at the Ravaged Caravan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[750] = { title = "The Hunt Continues", description = "A tauren skilled in the ways of the hunt knows that his prey is not for mere trophy. The beasts of the plains provide us with a means of survival. You will make quite an impression on the elders if you can bring back some highly valued Mountain Cougar Pelts. You can find the beasts lurking in the hills to the south.\n\nOur children need clothing and our tents need mending.", objectives = "Grull Hawkwind in Camp Narache wants you to bring him 10 Mountain Cougar Pelts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[751] = { title = "The Ravaged Caravan", description = "Prying open the lid reveals a tightly packed assortment of ore and minerals, more evidence of the Venture Co.'s mining operation in Mulgore. On the top of the ore and minerals you remove a tightly bound sheaf of papers.\n\nUp in the foothills to the east, you can barely hear the sounds of work, and see smoke rising from a large fire.", objectives = "Return the Venture Co. Documents to Morin Cloudstalker near Bloodhoof Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[752] = { title = "A Humble Task", description = "All members of the tribe share in the harmony of life. We live together and work together.\n\nOur commitment to one another carries with it a high degree of responsibility. I ask of you now a humble task.\n\nMy mother set out this morning to fetch water from the well to the southeast of Narache. It has been quite some time now. Perhaps you could check on her for me while I attend to tribal matters here?", objectives = "Chief Hawkwind wants you to search for his mother near the water well to the southeast of Camp Narache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[753] = { title = "A Humble Task", description = "I have traveled many paths through life and these old legs lack the vigor they once had. I can still perform my duties to the tribe. Sometimes it just takes an old woman a little longer to do the task.\n\nBut you look like an eager $c. Let's put some of that youthful vitality to the test. Take a water pitcher from the well and bring it to my son, the Chief, in Camp Narache.\n\nRemember that even the most humble task can gain the recognition of elders.", objectives = "Take a Water Pitcher from the water well.\n\nReturn the pitcher to Chief Hawkwind in Camp Narache which is northwest from the water well.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[754] = { title = "Winterhoof Cleansing", description = "I have crafted the totem to cleanse the Winterhoof Water Well.  Now, you must take it to the well and perform a cleansing ritual.  You will find it to the southeast, guarded by foul goblins!\n\nThis will not be an easy task, but you must do it if we are ever to use its waters again.\n\nFortune to you, $N.", objectives = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well, then return to Mull Thunderhorn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[755] = { title = "Rites of the Earthmother", description = "Your willingness to perform a humble task for the tauren of Narache and your eagerness to learn are noble traits, $n. I believe one day you will be heralded in Thunder Bluff as a $c of greatness.\n\nBefore that you must embark on the Rites of the Earthmother, of which there are three.\n\nThe first test is the Rite of Strength. Travel to Seer Graytongue and tell him Chief Hawkwind has sent you.\n\nYou will find the seer's abode directly to the south of Camp Narache, tucked away in the hills.", objectives = "Travel to Seer Graytongue who lives in the hills directly south of Camp Narache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[756] = { title = "Thunderhorn Totem", description = "To create the Thunderhorn Cleansing Totem, you must gather the claws of the predators of the Mulgore plains.  Hunt prairie stalkers for their stalker claws and flatland cougars for their cougar claws, then return to me.\n\nYou will find the prairie stalkers and flatland cougars to the east and west.", objectives = "Bring 6 Stalker Claws and 6 Cougar Claws to Mull Thunderhorn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[757] = { title = "Rite of Strength", description = "The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff.\n\nFirst you must pass the Rite of Strength. In this test you must prove your bravery by slaying enemies of the tribe.\n\nBristlebacks of Brambleblade Ravine to the east are encroaching on our tribal lands. They ambush our hunting parties and steal from the village by dark.\n\nShow your valor by slaying these villains and return to the Chief in Camp Narache with their belts as proof of your deeds.", objectives = "Kill Bristlebacks in Brambleblade Ravine and bring 12 Bristleback Belts to Chief Hawkwind in Camp Narache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[758] = { title = "Thunderhorn Cleansing", description = "The totem is ready, $N.  And again, it is your task to perform the ritual of cleansing.\n\nGo to the Thunderhorn Water Well, north of the village, and use the Thunderhorn Cleansing Totem in your ritual.  After you do this, return to me.\n\nMay the spirits guide you.", objectives = "Use the Thunderhorn Cleansing Totem at the Thunderhorn Water Well, then return to Mull.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[759] = { title = "Wildmane Totem", description = "There is but one water well left to cleanse, named after the Wildmane clan.  For this well to be pure, the land must offer the teeth of a fierce predator, the prairie wolf alpha.  Find the alphas to the north, then return to me when your hunt is finished.\n\nAlphas often wander around the base of our mighty city, Thunder Bluff.", objectives = "Bring 8 Prairie Alpha Teeth to Mull Thunderhorn in Bloodhoof Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[760] = { title = "Wildmane Cleansing", description = "Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young $N.  The Wildmane Totem is made, and your last task lies ahead.\n\nThe Wildmane Water Well lies north of Thunder Bluff.  Perform the ritual!  Heal the land of the goblins' poisons!  Let clean water flow once again!", objectives = "Use the Wildmane Cleansing Totem at the Wildmane Water Well, then return to Mull Thunderhorn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[761] = { title = "Swoop Hunting", description = "The swoop is a cunning bird, and difficult to find and hunt.  A collection of Swoop Quills is a badge of cleverness and determination for a hunter.\n\nIf you are willing to take up this task, then enter the plains and hunt the swoop.\n\nBring me their quills, and bring honor to your clan.\n\nThe swoops may be found anywhere in Mulgore, but your eyes must be sharp to spot them, and your hooves must be quick to catch them.", objectives = "Bring 8 Trophy Swoop Quills to Harken Windtotem in Bloodhoof Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[762] = { title = "An Ambassador of Evil", description = "Ambassador Infernus was sent to Angor Fortress by Ragnaros himself to mind the Shadowforge seeking lost artifacts in Uldaman.\n\nIt has already meant tremendous casualties for our people, but it has obviously grown worse. I hesitate to guess how many artifacts they would be able to find and use against Ironforge.\n\nOur goal is simple, $c. Return to the Badlands and destroy Ambassador Infernus. Once the threat is eliminated, return to Advisor Belgrum with proof of your victory.\n\nIt is in your hands now.", objectives = "Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[763] = { title = "Rites of the Earthmother", description = "For you to continue with the Rites of the Earthmother you must pass two more tests. It is time for you to broaden your experience, $n.\n\nTravel to Bloodhoof Village and seek out the Chief, Baine Bloodhoof, son of Cairne. There you may continue your journey and earn the acceptance of the elders of Thunder Bluff.\n\nTake this totem to Baine. He will recognize my carvings and help you on your path.\n\nFollow the road out of Camp Narache and travel with haste. Do not stray or you will lose your way.", objectives = "Take the Totem of Hawkwind to Baine Bloodhoof in Bloodhoof Village. Follow the road out of Camp Narache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[764] = { title = "The Venture Co.", description = "This explains the buildup of Venture Co. employees and equipment we've seen in Mulgore. Those goblins... their company is expanding too quickly for their own good. It's how they say, show a goblin something, and you can hear the scales in the background.\n\nGreedy little things, they are. Unfortunately for their business enterprise, we tauren cannot allow them to conduct their operations in our lands. Go to their mine northeast of the ravaged caravan and send them a message.", objectives = "Kill 14 Venture Co. Workers and 6 Venture Co. Supervisors for Morin Cloudstalker at Bloodhoof Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[765] = { title = "Supervisor Fizsprocket", description = "According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands.\n\nThe depths that they would sink to accomplish their goals disgusts and appalls me. I want the mastermind behind their plans killed. His name is Supervisor Fizsprocket, you will find him at the Venture Co. mine east of the ravaged caravan. Bring me his clipboard, we shall see if we find out anything useful.", objectives = "Kill Supervisor Fizsprocket and return his clipboard to Morin Cloudstalker at Bloodhoof Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[766] = { title = "Mazzranache", description = "My grandfather told me stories about his battles with a strider named Mazzranache. He told me of its demonic red eyes, razor-sharp talons and venomous bite.\n\nAs fortune would have it, while traveling across the plains, I encountered it, and it took a nasty bite from my shoulder. He was as terrible as my grandfather described. I will need some hard-to-find animal parts to clean the infection from his bite: a wolf heart, cougar femur, plainstrider scale and swoop gizzard.\n\nHurry, time is of the essence.", objectives = "Bring a Prairie Wolf Heart, Flatland Cougar Femur, Plainstrider Scale and Swoop Gizzard to Maur Raincaller at Bloodhoof Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[767] = { title = "Rite of Vision", description = "The Rite of Vision, one of the Rites of the Earthmother, will help guide you toward earning the respect of the elders of Thunder Bluff.\n\nOur people have learned that the land is our most holy provider. In order to take part in the ritualistic vision, you must speak with the spiritual leader of the village, Zarlman Two-Moons.", objectives = "Speak with Zarlman Two-Moons in Bloodhoof Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[768] = { title = "Gathering Leather", description = "Greetings, young one.  You have a gleam in your eye; I can tell you are eager to venture back to the plains for the hunt.  May you bring honor to your clan!\n\nI work with the skins of beasts, fashioning them into clothes and armor for the people of Thunder Bluff.\n\nIf you hunt beasts and bring me their skins, then I will fashion something for you.", objectives = "Bring 12 pieces of Light Leather to Veren Tallstrider in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[769] = { title = "Kodo Hide Bag", description = "The kodo beasts of Mulgore are strong and sturdy -- traits much respected among us.  If you are skilled in leatherworking and wish the knowledge to make a Kodo Hide Bag, then bring me supplies for my trade.\n\nDo this, and I will share my knowledge with you.", objectives = "Bring 4 Light Leather and 4 Coarse Thread to Veren Tallstrider in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[770] = { title = "The Demon Scarred Cloak", description = "The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion.\n\nPerhaps someone in Bloodhoof Village should know of Ghost Howl's demise....", objectives = "Find someone who knows of Ghost Howl.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[771] = { title = "Rite of Vision", description = "In order to pass through the Rite of Vision, you must gather the reagents needed to make the Water of the Seers.\n\nI will need well stones, which can be found around the water wells in Mulgore. With those I will combine Ambercorn, which fall beneath the mighty trees in our land.\n\nThese reagents contain magical elements, and when brewed and consumed before the tribal fire, will cause you to encounter a vision. Follow it, and it will lead you to the next step of this holy quest.", objectives = "Collect 2 Well Stones and 2 Ambercorn and bring them back to Zarlman Two-Moons in Bloodhoof Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[772] = { title = "Rite of Vision", description = "I now present you with the Water of the Seers.\n\nWhen you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, it will take a few moments before the vision materializes before the fire.\n\nAt that point, it is up to you to follow it to your destiny....", objectives = "Consume the Water of the Seers in front of the tribal fire in Bloodhoof Village and follow the vision once it appears.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[773] = { title = "Rite of Wisdom", description = "To gain acceptance amongst the elders of Thunder Bluff you must next complete the Rite of Wisdom.\n\nNow that you have passed the Rite of Vision, the ancestral spirits of Red Rocks will give you the blessing of our ancestors. Only those who have drunk from the Water of Seers can gain the blessing.\n\nTravel east of Thunder Bluff, to Red Rocks and seek out the Ancestral Spirit, $n.", objectives = "Travel to Red Rocks east of Thunder Bluff and speak with the Ancestral Spirit.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[775] = { title = "Journey into Thunder Bluff", description = "You will now be revered within our great city. Any $r worthy of completing the Rites of the Earthmother earns that honor.\n\nFor your final quest, seek out our noble leader, Cairne Bloodhoof, who dwells atop the highest mesa in Thunder Bluff.", objectives = "Speak with Cairne Bloodhoof in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[776] = { title = "Rites of the Earthmother", description = "You have passed the Rites of the Earthmother and earned your place in Thunder Bluff.\n\nBut in order to maintain the spot that you strived so hard to achieve, you must continue to prove your worth to your people.\n\nWe are hunters, $n. Down below in Mulgore there is a mighty kodo named Arra'chea. Show me your skills in the ways of tracking and hunting by bringing me the Horn of Arra'chea.", objectives = "Cairne Bloodhoof in Thunder Bluff wants you to bring him the Horn of Arra'chea.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[777] = { title = "This Is Going to Be Hard", description = "Okay, here you go.\n\nI'm going to be over here... behind cover.\n\nFeel free to join me.", objectives = "Bring Cog #5 to Lotwil Veriatus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[778] = { title = "This Is Going to Be Hard", description = "Haha! Done! The shackles are done!\n\nIt's time, Lucien. It's time, Servo!\n\nAre you ready to bear witness to the perfect blend of alchemy, engineering, and the arcane, $N?\n\nI shall summon forth a powerful elemental now. This is a groundbreaking day for all of us.", objectives = "Defeat the Fam'retor Guardian and bring Lotwil's Shackles of Elemental Binding back to Lotwil Veriatus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[779] = { title = "Seal of the Earth", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[780] = { title = "The Battleboars", description = "The Battleboars of Brambleblade Ravine to the east are encroaching on our tribal hunting grounds. They are trained to be malicious by the Bristleback Quilboars with whom we are at war.\n\nGo and slay the vile creatures and bring back some snouts and flanks so that we can make stew for our young.", objectives = "Grull Hawkwind in Camp Narache wants you to kill Battleboars and bring back 8 Battleboar Snouts and 8 Battleboar Flanks.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[781] = { title = "Attack on Camp Narache", description = "After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache.\n\nSurely Chief Hawkwind could use this information!", objectives = "Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[782] = { title = "Broken Alliances", description = "From the Horde's alliance with the dragon Deathwing during the Second War, we know that two of his lieutenants, Blacklash and Hematus, were imprisoned within Lethlor Ravine far to the east. We must silence our depraved allies of old to restore honor to the Horde!\n\nWe hired Tho'grun and his band of ogre mercenaries to help us obtain the Sign of the Earth, a key needed to unlock the drakes' prison. Tho'grun betrayed us though, overwhelming us and taking it for himself. Go to Camp Boff and take it back!", objectives = "Kill Boss Tho'grun and bring the Sign of the Earth to Gorn in Kargath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
